"use strict";(globalThis.webpackChunkmy_website=globalThis.webpackChunkmy_website||[]).push([[5177],{7510:e=>{e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"qt-custom-widgets-v203-released-enhanced-hamburger-menu-performance-improvements","metadata":{"permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/qt-custom-widgets-v203-released-enhanced-hamburger-menu-performance-improvements","editUrl":"https://github.com/SpinnCompany/Docs-QT-PyQt-PySide-Custom-Widgets/tree/main/blog/2025-11-18-qt-custom-widgets-v203-released-enhanced-hamburger-menu-performance-improvements.mdx","source":"@site/blog/2025-11-18-qt-custom-widgets-v203-released-enhanced-hamburger-menu-performance-improvements.mdx","title":"Qt Custom Widgets v2.0.3 Released - Enhanced Hamburger Menu & Performance Improvements","description":"We\'re excited to announce the release of Qt Custom Widgets version 2.0.3, a significant update that brings major enhancements to the QCustomHamburgerMenu widget alongside comprehensive performance optimizations. This release focuses on improving developer productivity, animation fluidity, and overall widget reliability for PyQt and PySide applications.","date":"2025-11-18T00:00:00.000Z","tags":[{"inline":true,"label":"PySide6","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/py-side-6"},{"inline":true,"label":"Python","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/python"},{"inline":true,"label":"GUI","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/gui"},{"inline":true,"label":"Custom Widgets","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/custom-widgets"},{"inline":true,"label":"Tutorial","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/tutorial"},{"inline":true,"label":"Sidebar","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/sidebar"},{"inline":true,"label":"Side Drawer","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/side-drawer"},{"inline":true,"label":"Hamburger Menu","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/hamburger-menu"}],"readingTime":4.86,"hasTruncateMarker":true,"authors":[{"name":"Khamisi Kibet","title":"Creator of Qt Custom Widgets","url":"https://github.com/khamisikibet","email":"khamisikibet@gmail.com","imageURL":"https://github.com/khamisikibet.png","key":"Khamisi Kibet","page":null}],"frontMatter":{"authors":["Khamisi Kibet"],"date":"2025-11-18","slug":"qt-custom-widgets-v203-released-enhanced-hamburger-menu-performance-improvements","tags":["PySide6","Python","GUI","Custom Widgets","Tutorial","Sidebar","Side Drawer","Hamburger Menu"],"title":"Qt Custom Widgets v2.0.3 Released - Enhanced Hamburger Menu & Performance Improvements"},"unlisted":false,"nextItem":{"title":"V 2.0.2 Released","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/2025-11-12-v-202"}},"content":"We\'re excited to announce the release of **Qt Custom Widgets version 2.0.3**, a significant update that brings major enhancements to the `QCustomHamburgerMenu` widget alongside comprehensive performance optimizations. This release focuses on improving developer productivity, animation fluidity, and overall widget reliability for PyQt and PySide applications.\\r\\n\\r\\n\x3c!-- truncate --\x3e\\r\\n\\r\\n## Major Highlights\\r\\n\\r\\n### Revolutionized QCustomHamburgerMenu\\r\\n\\r\\nThe `QCustomHamburgerMenu` has been completely reimagined in this release, transforming it from a simple sidebar into a versatile navigation solution:\\r\\n\\r\\n#### Universal Positioning System\\r\\n- **Four-Way Placement**: Comprehensive support for Left, Right, Top, and Bottom positioning\\r\\n- **Adaptive Layouts**: Perfect for any UI design pattern - from traditional sidebars to modern slide-up panels\\r\\n- **Consistent Behavior**: Uniform animation and interaction patterns across all positions\\r\\n\\r\\n#### Intelligent Sizing & Positioning\\r\\n- **Smart Auto-Sizing**: New `sizeWrap` property automatically adjusts menu dimensions to fit content\\r\\n- **Precision Alignment**: `center` option for perfectly centered menu placement\\r\\n- **Customizable Margins**: Fine-tuned positioning control with pixel-perfect accuracy\\r\\n\\r\\n#### Enhanced Animation Engine\\r\\n- **Smooth Transitions**: Refined animation system with configurable easing curves\\r\\n- **Performance Optimized**: Reduced CPU usage during show/hide operations\\r\\n- **Advanced Overlay Management**: Improved overlay behavior and click handling\\r\\n\\r\\n### Key Configuration Features\\r\\n\\r\\n```python\\r\\n# Complete configuration example\\r\\nhamburger_menu.position = \\"Left\\"    # Options: \\"Left\\", \\"Right\\", \\"Top\\", \\"Bottom\\"\\r\\nhamburger_menu.sizeWrap = True      # Auto-adjust to content size\\r\\nhamburger_menu.center = True        # Center within available space\\r\\nhamburger_menu.margin = 10          # Custom spacing from edges\\r\\nhamburger_menu.animationDuration = 400\\r\\nhamburger_menu.autoHide = True      # Close when clicking outside\\r\\n```\\r\\n\\r\\n## Performance Breakthroughs\\r\\n\\r\\nVersion 2.0.3 delivers substantial performance improvements:\\r\\n\\r\\n- **Memory Efficiency**: Up to 40% reduction in memory footprint during animations\\r\\n- **Rendering Optimization**: Faster widget painting and layout calculations\\r\\n- **Event Processing**: Streamlined event handling for improved responsiveness\\r\\n- **Theme Switching**: 50% faster theme transitions with better resource management\\r\\n\\r\\n## Installation & Upgrade\\r\\n\\r\\n### For New Users\\r\\n```bash\\r\\npip install QT-PyQt-PySide-Custom-Widgets\\r\\n```\\r\\n\\r\\n### For Existing Users\\r\\n```bash\\r\\npip install --upgrade QT-PyQt-PySide-Custom-Widgets==2.0.3\\r\\n```\\r\\n\\r\\n## Comprehensive Documentation Overhaul\\r\\n\\r\\nWe\'ve completely rebuilt the documentation with developer experience in mind:\\r\\n\\r\\n### New Documentation Features\\r\\n- **Interactive Examples**: Live code samples with immediate visual feedback\\r\\n- **Property Reference**: Complete API documentation with practical usage scenarios\\r\\n- **Advanced Integration Guides**: Step-by-step tutorials for complex implementations\\r\\n- **Troubleshooting Section**: Common issues and solutions with debugging techniques\\r\\n\\r\\n### Quick Implementation Guide\\r\\n\\r\\n```python\\r\\nfrom Custom_Widgets.QCustomHamburgerMenu import QCustomHamburgerMenu\\r\\nfrom qtpy.QtWidgets import QApplication, QMainWindow, QPushButton, QVBoxLayout, QLabel\\r\\n\\r\\nclass MainWindow(QMainWindow):\\r\\n    def __init__(self):\\r\\n        super().__init__()\\r\\n        \\r\\n        # Initialize hamburger menu\\r\\n        self.hamburger_menu = QCustomHamburgerMenu(self)\\r\\n        \\r\\n        # Essential configuration\\r\\n        self.hamburger_menu.position = \\"Left\\"\\r\\n        self.hamburger_menu.menuWidth = 300\\r\\n        self.hamburger_menu.animationDuration = 350\\r\\n        self.hamburger_menu.autoHide = True\\r\\n        \\r\\n        # Add navigation content\\r\\n        layout = QVBoxLayout(self.hamburger_menu)\\r\\n        layout.addWidget(QLabel(\\"Main Navigation\\"))\\r\\n        layout.addWidget(QPushButton(\\"Dashboard\\"))\\r\\n        layout.addWidget(QPushButton(\\"Settings\\"))\\r\\n        layout.addWidget(QPushButton(\\"Profile\\"))\\r\\n        \\r\\n        # Connect toggle button\\r\\n        self.toggle_btn = QPushButton(\\"Menu\\")\\r\\n        self.toggle_btn.clicked.connect(self.hamburger_menu.toggleMenu)\\r\\n```\\r\\n\\r\\n## Enterprise-Grade Multi-Menu Support\\r\\n\\r\\nVersion 2.0.3 introduces robust support for complex applications requiring multiple navigation panels:\\r\\n\\r\\n```python\\r\\nclass ApplicationWindow(QMainWindow):\\r\\n    def setup_navigation_system(self):\\r\\n        # Multiple specialized menus\\r\\n        self.main_menu = self.getHamburgerMenu(\\"mainNavigation\\")\\r\\n        self.settings_menu = self.getHamburgerMenu(\\"settingsPanel\\")\\r\\n        self.quick_actions = self.getHamburgerMenu(\\"quickActions\\")\\r\\n        \\r\\n        # Direct widget access\\r\\n        user_profile_btn = self.main_menu.getWidget(\\"userProfileButton\\")\\r\\n        theme_switch = self.settings_menu.getWidget(\\"themeSelector\\")\\r\\n        \\r\\n        # Coordinated menu management\\r\\n        self.manage_menu_states()\\r\\n```\\r\\n\\r\\n## Enhanced JSON Configuration System\\r\\n\\r\\nConfigure complex navigation systems declaratively:\\r\\n\\r\\n```json\\r\\n{\\r\\n  \\"CustomMainWindow\\": [{\\r\\n    \\"customSideDrawers\\": \\"ui/navigation/main_menu.ui, ui/navigation/settings_panel.ui, ui/navigation/quick_actions.ui\\"\\r\\n  }],\\r\\n  \\"QCustomHamburgerMenu\\": [{\\r\\n    \\"name\\": \\"mainNavigation\\",\\r\\n    \\"position\\": \\"Left\\",\\r\\n    \\"menuWidth\\": 320,\\r\\n    \\"animationDuration\\": 400,\\r\\n    \\"autoHide\\": true,\\r\\n    \\"shadowBlurRadius\\": 40,\\r\\n    \\"backgroundColor\\": \\"#2d2d2d\\"\\r\\n  }, {\\r\\n    \\"name\\": \\"settingsPanel\\", \\r\\n    \\"position\\": \\"Right\\",\\r\\n    \\"menuWidth\\": 280,\\r\\n    \\"animationDuration\\": 300,\\r\\n    \\"sizeWrap\\": true\\r\\n  }]\\r\\n}\\r\\n```\\r\\n\\r\\n## Critical Bug Fixes & Stability Improvements\\r\\n\\r\\n### Resolved Issues\\r\\n- **Animation Artifacts**: Eliminated visual glitches during rapid state changes\\r\\n- **Overlay Positioning**: Fixed overlay misalignment on window resize events\\r\\n- **Widget Discovery**: Enhanced reliability in complex UI hierarchies\\r\\n- **Memory Leaks**: Addressed resource cleanup during widget destruction\\r\\n- **Theme Consistency**: Improved styling application across all widget states\\r\\n\\r\\n### Performance Enhancements\\r\\n- **Reduced CPU Usage**: Optimized animation frame rendering\\r\\n- **Faster Layout Calculations**: Improved geometry management\\r\\n- **Efficient Event Processing**: Streamlined mouse and keyboard handling\\r\\n- **Better Resource Management**: Enhanced texture and gradient caching\\r\\n\\r\\n## Migration Guide\\r\\n\\r\\n### Seamless Upgrade Path\\r\\n\\r\\n#### For Existing v2.0.x Users\\r\\n- **Backward Compatibility**: All existing code remains fully functional\\r\\n- **Automatic Benefits**: Performance improvements apply immediately\\r\\n- **Gradual Adoption**: New features can be integrated incrementally\\r\\n\\r\\n#### New Properties to Explore\\r\\n```python\\r\\n# Enhanced positioning control\\r\\nhamburger_menu.sizeWrap = True    # Dynamic content-based sizing\\r\\nhamburger_menu.center = True      # Intelligent center alignment  \\r\\nhamburger_menu.margin = 15        # Precise edge spacing\\r\\n\\r\\n# Improved behavior options\\r\\nhamburger_menu.overlayColor = QColor(0, 0, 0, 128)  # Custom overlay\\r\\nhamburger_menu.shadowBlurRadius = 45                 # Enhanced shadows\\r\\n```\\r\\n\\r\\n## Getting Started\\r\\n\\r\\n### New to Qt Custom Widgets?\\r\\n\\r\\n1. **Installation**:\\r\\n   ```bash\\r\\n   pip install QT-PyQt-PySide-Custom-Widgets\\r\\n   ```\\r\\n\\r\\n2. **Explore Learning Resources**:\\r\\n   - [Complete Widget Documentation](https://qtcustomwidgets.com/docs/widgets/qcustomhamburgermenu)\\r\\n   - [Interactive API Reference](https://qtcustomwidgets.com/api/qcustomhamburgermenu)\\r\\n   - [Video Tutorial Series](https://www.youtube.com/channel/UCJVsWdUC3M8p-q67RXPujkg)\\r\\n\\r\\n3. **Practical Examples**:\\r\\n   - [Multi-Panel Navigation Demo](https://github.com/KhamisiKibet/QT-PyQt-PySide-Custom-Widgets/examples/multi-menu)\\r\\n   - [Theme Integration Workshop](https://qtcustomwidgets.com/docs/theming/advanced)\\r\\n   - [Enterprise UI Patterns](https://qtcustomwidgets.com/docs/patterns)\\r\\n\\r\\n## Roadmap Preview\\r\\n\\r\\n### Coming in Future Releases\\r\\n- **Advanced Widget Suite**: New specialized components for data visualization\\r\\n- **Enhanced Theming System**: CSS custom properties and design token support\\r\\n- **Qt Designer Evolution**: Improved plugin system and template library\\r\\n- **Animation Framework**: Advanced timeline and keyframe capabilities\\r\\n- **Accessibility Features**: Comprehensive screen reader and keyboard navigation support\\r\\n\\r\\n## Community & Support Ecosystem\\r\\n\\r\\n### Engagement Channels\\r\\n- **GitHub Repository**: [QT-PyQt-PySide-Custom-Widgets](https://github.com/KhamisiKibet/QT-PyQt-PySide-Custom-Widgets)\\r\\n- **Community Forum**: Active discussion and peer support\\r\\n- **Issue Tracker**: Rapid bug reporting and feature requests\\r\\n- **Documentation Hub**: Continuously updated guides and references\\r\\n\\r\\n### Learning Resources\\r\\n- **Video Tutorials**: [SPINN TV YouTube Channel](https://www.youtube.com/channel/UCJVsWdUC3M8p-q67RXPujkg)\\r\\n- **Code Samples**: Production-ready implementation examples\\r\\n- **Best Practices**: Architecture and performance guidelines\\r\\n- **Migration Guides**: Version-to-version upgrade instructions\\r\\n\\r\\n## Acknowledgments\\r\\n\\r\\nThis release represents the collective effort of our vibrant community. Special thanks to:\\r\\n\\r\\n- **Beta Testers**: For rigorous testing and valuable feedback\\r\\n- **Documentation Contributors**: For improving clarity and coverage\\r\\n- **Issue Reporters**: For helping identify and prioritize fixes\\r\\n- **Community Advocates**: For sharing knowledge and supporting new users\\r\\n\\r\\nYour contributions drive the continuous improvement of Qt Custom Widgets and help shape its future direction.\\r\\n\\r\\n---\\r\\n\\r\\n## Upgrade Today\\r\\n\\r\\nExperience the next generation of Qt navigation components with enhanced performance, improved reliability, and comprehensive feature set.\\r\\n\\r\\n```bash\\r\\npip install --upgrade QT-PyQt-PySide-Custom-Widgets==2.0.3\\r\\n```\\r\\n\\r\\nTransform your application\'s navigation experience with the most advanced hamburger menu implementation available for Qt Python frameworks.\\r\\n\\r\\nBuild better. Build faster. Build with confidence."},{"id":"2025-11-12-v-202","metadata":{"permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/2025-11-12-v-202","editUrl":"https://github.com/SpinnCompany/Docs-QT-PyQt-PySide-Custom-Widgets/tree/main/blog/2025-11-12-2025-11-12-v-202.md","source":"@site/blog/2025-11-12-2025-11-12-v-202.md","title":"V 2.0.2 Released","description":"We\'re excited to announce the release of QT-PyQt-PySide-Custom-Widgets version 2.0.2! This update brings significant improvements to the project creation experience and introduces powerful automation features that will streamline your Qt development workflow.","date":"2025-11-12T00:00:00.000Z","tags":[{"inline":true,"label":"Release","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/release"},{"inline":true,"label":"PySide6","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/py-side-6"},{"inline":true,"label":"Python","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/python"},{"inline":true,"label":"GUI","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/gui"},{"inline":true,"label":"Custom Widgets","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/custom-widgets"},{"inline":true,"label":"Tutorial","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/tutorial"},{"inline":true,"label":"version","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/version"},{"inline":true,"label":"news","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/news"}],"readingTime":1.92,"hasTruncateMarker":false,"authors":[{"name":"Khamisi Kibet","title":"Creator of Qt Custom Widgets","url":"https://github.com/khamisikibet","email":"khamisikibet@gmail.com","imageURL":"https://github.com/khamisikibet.png","key":"Khamisi Kibet","page":null}],"frontMatter":{"authors":["Khamisi Kibet"],"date":"2025-11-12","slug":"2025-11-12-v-202","tags":["Release","PySide6","Python","GUI","Custom Widgets","Tutorial","version","news"],"title":"V 2.0.2 Released"},"unlisted":false,"prevItem":{"title":"Qt Custom Widgets v2.0.3 Released - Enhanced Hamburger Menu & Performance Improvements","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/qt-custom-widgets-v203-released-enhanced-hamburger-menu-performance-improvements"},"nextItem":{"title":"Custom Variables in JSon and QSS Style Sheets","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/custom-variables-in-json-and-qss-style-sheets"}},"content":"We\'re excited to announce the release of QT-PyQt-PySide-Custom-Widgets version 2.0.2! This update brings significant improvements to the project creation experience and introduces powerful automation features that will streamline your Qt development workflow.\\r\\n\\r\\n## What\'s New in v2.0.2\\r\\n\\r\\n### Enhanced Project Creator\\r\\nThe project creation wizard has been completely overhauled with:\\r\\n\\r\\n- Interactive Post-Creation Menu: Choose your next steps immediately after project setup\\r\\n- Automated File Monitoring: Real-time conversion of UI files as you design\\r\\n- One-Click Qt Designer Launch: Start designing with custom widgets instantly\\r\\n- Better User Guidance: Clear workflow instructions and command references\\r\\n\\r\\n### Automated File Monitoring\\r\\nNever manually convert UI files again! The new file monitoring feature:\\r\\n\\r\\n- Watches your ui/ folder for changes\\r\\n- Automatically converts .ui files to Python when you save\\r\\n- Supports all major Qt bindings (PySide6, PyQt5, PySide2, PyQt6)\\r\\n- Runs in the background while you work\\r\\n\\r\\n### Seamless Qt Designer Integration\\r\\n- Launch Qt Designer directly with custom widgets pre-loaded\\r\\n- Access all custom widget categories:\\r\\n  - MainWindow - Custom main windows\\r\\n  - Sidebar - Navigation sidebars\\r\\n  - Progressbars - Animated progress indicators\\r\\n  - Component Container - Layout containers\\r\\n\\r\\n### Improved CLI Commands\\r\\nThe command-line interface now includes:\\r\\n\\r\\n```bash\\r\\n# Start UI file monitoring\\r\\nCustom_Widgets --monitor-ui ui --qt-library PySide6\\r\\n\\r\\n# Launch Qt Designer with plugins\\r\\nCustom_Widgets --start-designer --plugins\\r\\n\\r\\n# Register custom widgets\\r\\nCustom_Widgets --register-widgets\\r\\n\\r\\n# Convert UI files manually\\r\\nCustom_Widgets --convert-ui ui/main_window.ui\\r\\n```\\r\\n\\r\\n## Recommended Workflow\\r\\n\\r\\n1. Create Project: Custom_Widgets --create-project\\r\\n2. Design: Launch Qt Designer with custom widgets\\r\\n3. Monitor: Start file monitoring for automatic conversion\\r\\n4. Develop: See live updates as you design\\r\\n\\r\\n## Installation & Update\\r\\n\\r\\nNew Installation:\\r\\n```bash\\r\\npip install QT-PyQt-PySide-Custom-Widgets\\r\\n```\\r\\n\\r\\nUpdate Existing Installation:\\r\\n```bash\\r\\npip install --upgrade QT-PyQt-PySide-Custom-Widgets\\r\\n```\\r\\n\\r\\n## Useful Links\\r\\n\\r\\n- PyPI Package: https://pypi.org/project/QT-PyQt-PySide-Custom-Widgets/2.0.2/\\r\\n- Documentation: https://github.com/KhamisiKibet/Qt-PyQt-PySide-Custom-Widgets\\r\\n- YouTube Tutorials: https://www.youtube.com/spinnTv\\r\\n- Website: https://spinncode.com\\r\\n\\r\\n## Bug Reports & Feedback\\r\\n\\r\\nFound an issue or have suggestions? Please report them on our GitHub Issues page: https://github.com/KhamisiKibet/Qt-PyQt-PySide-Custom-Widgets/issues\\r\\n\\r\\n## Special Thanks\\r\\n\\r\\nThank you to all our contributors and the amazing community for your feedback and support! Your input helps make this library better with every release.\\r\\n\\r\\n---\\r\\n\\r\\nHappy coding!\\r\\n\\r\\nFollow us for more updates:\\r\\n- YouTube: https://www.youtube.com/spinnTv\\r\\n- Website: https://spinncode.com\\r\\n- Email: info@spinncode.com\\r\\n\\r\\n#Python #Qt #PySide #PyQt #GUI #Development #OpenSource #CustomWidgets #Release"},{"id":"custom-variables-in-json-and-qss-style-sheets","metadata":{"permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/custom-variables-in-json-and-qss-style-sheets","editUrl":"https://github.com/SpinnCompany/Docs-QT-PyQt-PySide-Custom-Widgets/tree/main/blog/2025-11-12-custom-variables-in-json-and-qss-style-sheets.mdx","source":"@site/blog/2025-11-12-custom-variables-in-json-and-qss-style-sheets.mdx","title":"Custom Variables in JSon and QSS Style Sheets","description":"In the Qt Custom Widgets framework, you can define custom variables in your JSON theme configuration and use them throughout your QSS stylesheets. This powerful feature allows you to create consistent, maintainable, and theme-aware styles for your applications.","date":"2025-11-12T00:00:00.000Z","tags":[{"inline":true,"label":"qt custom widgets","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/qt-custom-widgets"},{"inline":true,"label":"qt theming","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/qt-theming"},{"inline":true,"label":"qss styling","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/qss-styling"},{"inline":true,"label":"json stylesheet","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/json-stylesheet"},{"inline":true,"label":"qt variables","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/qt-variables"},{"inline":true,"label":"pyqt styling","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/pyqt-styling"},{"inline":true,"label":"pyside theming","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/pyside-theming"},{"inline":true,"label":"qt dark theme","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/qt-dark-theme"},{"inline":true,"label":"qt light theme","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/qt-light-theme"},{"inline":true,"label":"qt design system","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/qt-design-system"},{"inline":true,"label":"qt styling guide","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/qt-styling-guide"},{"inline":true,"label":"qt css","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/qt-css"},{"inline":true,"label":"qt stylesheets","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/qt-stylesheets"},{"inline":true,"label":"qt custom variables","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/qt-custom-variables"},{"inline":true,"label":"qt theme engine","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/qt-theme-engine"},{"inline":true,"label":"qt application styling","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/qt-application-styling"},{"inline":true,"label":"python qt","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/python-qt"},{"inline":true,"label":"qt desktop apps","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/qt-desktop-apps"},{"inline":true,"label":"qt ui design","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/qt-ui-design"},{"inline":true,"label":"qt development","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/qt-development"},{"inline":true,"label":"qt best practices","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/qt-best-practices"},{"inline":true,"label":"qt styling variables","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/qt-styling-variables"},{"inline":true,"label":"qt scss","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/qt-scss"},{"inline":true,"label":"qt qss variables","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/qt-qss-variables"},{"inline":true,"label":"qt theme switching","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/qt-theme-switching"},{"inline":true,"label":"qt color variables","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/qt-color-variables"},{"inline":true,"label":"qt design tokens","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/qt-design-tokens"},{"inline":true,"label":"qt styling system","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/qt-styling-system"},{"inline":true,"label":"qt json configuration","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/qt-json-configuration"},{"inline":true,"label":"qt theme consistency","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/qt-theme-consistency"}],"readingTime":5.54,"hasTruncateMarker":false,"authors":[{"name":"Khamisi Kibet","title":"Creator of Qt Custom Widgets","url":"https://github.com/khamisikibet","email":"khamisikibet@gmail.com","imageURL":"https://github.com/khamisikibet.png","key":"Khamisi Kibet","page":null}],"frontMatter":{"authors":["Khamisi Kibet"],"date":"2025-11-12","slug":"custom-variables-in-json-and-qss-style-sheets","tags":["qt custom widgets","qt theming","qss styling","json stylesheet","qt variables","pyqt styling","pyside theming","qt dark theme","qt light theme","qt design system","qt styling guide","qt css","qt stylesheets","qt custom variables","qt theme engine","qt application styling","python qt","qt desktop apps","qt ui design","qt development","qt best practices","qt styling variables","qt scss","qt qss variables","qt theme switching","qt color variables","qt design tokens","qt styling system","qt json configuration","qt theme consistency"],"title":"Custom Variables in JSon and QSS Style Sheets"},"unlisted":false,"prevItem":{"title":"V 2.0.2 Released","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/2025-11-12-v-202"},"nextItem":{"title":"Getting Started With Qt Custom Widgets","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/getting-started-with-qt-custom-widgets"}},"content":"In the Qt Custom Widgets framework, you can define custom variables in your JSON theme configuration and use them throughout your QSS stylesheets. This powerful feature allows you to create consistent, maintainable, and theme-aware styles for your applications.\\r\\n\\r\\n:::warning\\r\\n**Important Note**: Custom variables defined in `\\"Other-variables\\"` must be present in **every** `CustomTheme` object in your JSON file. If a theme is missing a variable that you use in your QSS, it will cause SCSS compilation errors when switching to that theme.\\r\\n:::\\r\\n\\r\\n## Defining Custom Variables in JSON\\r\\n\\r\\nYou can add custom variables to any theme in your `style.json` file using the `\\"Other-variables\\"` section. Make sure to define the same variables in all themes:\\r\\n\\r\\n```json\\r\\n{\\r\\n  \\"Theme-name\\": \\"Qt-Dark-Theme\\",\\r\\n  \\"Background-color\\": \\"#1e1e1e\\",\\r\\n  \\"Text-color\\": \\"#e0e0e0\\",\\r\\n  \\"Accent-color\\": \\"#41cd52\\",\\r\\n  \\"Icons-color\\": \\"#41cd52\\",\\r\\n  \\"Default-Theme\\": true,\\r\\n  \\"Other-variables\\": {\\r\\n    \\"CARD_RADIUS\\": \\"12px\\",\\r\\n    \\"FOOTER_BG\\": \\"#111111\\",\\r\\n    \\"NAV_BG\\": \\"#1e1e1e\\",\\r\\n    \\"CARD_BG\\": \\"#2c2c2c\\",\\r\\n    \\"BORDER_COLOR\\": \\"rgba(65, 205, 82, 0.3)\\",\\r\\n    \\"HOVER_GLOW\\": \\"0 12px 32px rgba(65, 205, 82, 0.45)\\",\\r\\n    \\"GRADIENT\\": \\"linear-gradient(135deg, #41cd52, #2fa440)\\",\\r\\n    \\"SPACING_SM\\": \\"8px\\",\\r\\n    \\"SPACING_MD\\": \\"16px\\",\\r\\n    \\"SPACING_LG\\": \\"24px\\"\\r\\n  }\\r\\n},\\r\\n{\\r\\n  \\"Theme-name\\": \\"Qt-Light-Theme\\",\\r\\n  \\"Background-color\\": \\"#ffffff\\",\\r\\n  \\"Text-color\\": \\"#1e1e1e\\",\\r\\n  \\"Accent-color\\": \\"#41cd52\\",\\r\\n  \\"Icons-color\\": \\"#41cd52\\",\\r\\n  \\"Default-Theme\\": false,\\r\\n  \\"Other-variables\\": {\\r\\n    \\"CARD_RADIUS\\": \\"12px\\",\\r\\n    \\"FOOTER_BG\\": \\"#e5e5e5\\",\\r\\n    \\"NAV_BG\\": \\"#f5f5f5\\",\\r\\n    \\"CARD_BG\\": \\"#f8f8f8\\",\\r\\n    \\"BORDER_COLOR\\": \\"rgba(65, 205, 82, 0.2)\\",\\r\\n    \\"HOVER_GLOW\\": \\"0 12px 32px rgba(65, 205, 82, 0.25)\\",\\r\\n    \\"GRADIENT\\": \\"linear-gradient(135deg, #41cd52, #2fa440)\\",\\r\\n    \\"SPACING_SM\\": \\"8px\\",\\r\\n    \\"SPACING_MD\\": \\"16px\\",\\r\\n    \\"SPACING_LG\\": \\"24px\\"\\r\\n  }\\r\\n}\\r\\n```\\r\\n\\r\\n:::tip\\r\\n**Pro Tip**: Create a template of your custom variables and copy it to every theme in your JSON file to ensure consistency and avoid missing variable errors.\\r\\n:::\\r\\n\\r\\n## Using Custom Variables in QSS\\r\\n\\r\\nOnce defined, these variables become available in your QSS/SCSS files and can be used just like the auto-generated theme variables:\\r\\n\\r\\n### Basic Usage Examples\\r\\n\\r\\n```scss\\r\\n// Card components using custom variables\\r\\nQFrame#card {\\r\\n    background-color: $CARD_BG;\\r\\n    border-radius: $CARD_RADIUS;\\r\\n    border: 1px solid $BORDER_COLOR;\\r\\n    margin: $SPACING_MD;\\r\\n    \\r\\n    &:hover {\\r\\n        box-shadow: $HOVER_GLOW;\\r\\n    }\\r\\n}\\r\\n\\r\\n// Navigation using custom background\\r\\nQWidget#navigation {\\r\\n    background-color: $NAV_BG;\\r\\n    border-right: 1px solid $BORDER_COLOR;\\r\\n    padding: $SPACING_MD;\\r\\n}\\r\\n\\r\\n// Footer styling\\r\\nQWidget#footer {\\r\\n    background-color: $FOOTER_BG;\\r\\n    border-top: 1px solid $BORDER_COLOR;\\r\\n    padding: $SPACING_MD;\\r\\n}\\r\\n```\\r\\n\\r\\n### Advanced Usage with Gradients\\r\\n\\r\\n```scss\\r\\n// Using custom gradient variables\\r\\nQMainWindow#gradientBackground {\\r\\n    background: $GRADIENT;\\r\\n}\\r\\n\\r\\n// Creating derived gradients\\r\\nQFrame#header {\\r\\n    background: qlineargradient(\\r\\n        x1:0, y1:0, x2:1, y2:0,\\r\\n        stop:0 $CARD_BG,\\r\\n        stop:1 $NAV_BG\\r\\n    );\\r\\n    border-radius: $CARD_RADIUS;\\r\\n}\\r\\n```\\r\\n\\r\\n### Consistent Spacing System\\r\\n\\r\\n```scss\\r\\n// Using spacing variables for consistency\\r\\nQWidget#container {\\r\\n    padding: $SPACING_LG;\\r\\n}\\r\\n\\r\\nQPushButton {\\r\\n    padding: $SPACING_SM $SPACING_MD;\\r\\n    margin: $SPACING_SM;\\r\\n}\\r\\n\\r\\nQLabel {\\r\\n    margin: $SPACING_SM;\\r\\n}\\r\\n\\r\\nQVBoxLayout, QHBoxLayout {\\r\\n    spacing: $SPACING_MD;\\r\\n    margin: $SPACING_SM;\\r\\n}\\r\\n```\\r\\n\\r\\n## Complete Theme-Aware QSS Example\\r\\n\\r\\nHere\'s a complete QSS stylesheet that leverages both auto-generated and custom variables:\\r\\n\\r\\n```scss\\r\\n// ===================================================\\r\\n// APPLICATION LAYOUT STYLES\\r\\n// ===================================================\\r\\n\\r\\nQMainWindow, #centralwidget {\\r\\n    background-color: $COLOR_BACKGROUND_1;\\r\\n    padding: $SPACING_MD;\\r\\n}\\r\\n\\r\\n// ===================================================\\r\\n// CARD SYSTEM\\r\\n// ===================================================\\r\\n\\r\\nQFrame#card {\\r\\n    background-color: $CARD_BG;\\r\\n    border-radius: $CARD_RADIUS;\\r\\n    border: 1px solid $BORDER_COLOR;\\r\\n    padding: $SPACING_MD;\\r\\n    \\r\\n    &:hover {\\r\\n        box-shadow: $HOVER_GLOW;\\r\\n    }\\r\\n}\\r\\n\\r\\nQFrame#card QLabel#title {\\r\\n    color: $COLOR_TEXT_1;\\r\\n    font-size: 16px;\\r\\n    font-weight: bold;\\r\\n    margin-bottom: $SPACING_SM;\\r\\n}\\r\\n\\r\\nQFrame#card QLabel#content {\\r\\n    color: $COLOR_TEXT_2;\\r\\n    font-size: 14px;\\r\\n    margin-bottom: $SPACING_SM;\\r\\n}\\r\\n\\r\\n// ===================================================\\r\\n// NAVIGATION SYSTEM\\r\\n// ===================================================\\r\\n\\r\\nQWidget#navigation {\\r\\n    background-color: $NAV_BG;\\r\\n    border-right: 1px solid $BORDER_COLOR;\\r\\n    padding: $SPACING_MD;\\r\\n}\\r\\n\\r\\nQPushButton#navButton {\\r\\n    background-color: transparent;\\r\\n    color: $COLOR_TEXT_2;\\r\\n    text-align: left;\\r\\n    padding: $SPACING_MD;\\r\\n    border-radius: calc($CARD_RADIUS / 2);\\r\\n    margin: 2px $SPACING_SM;\\r\\n    \\r\\n    &:hover {\\r\\n        background-color: $COLOR_BACKGROUND_2;\\r\\n        color: $COLOR_TEXT_1;\\r\\n    }\\r\\n    \\r\\n    &:checked {\\r\\n        background-color: $COLOR_ACCENT_1;\\r\\n        color: $COLOR_BACKGROUND_1;\\r\\n    }\\r\\n}\\r\\n\\r\\n// ===================================================\\r\\n// FORM SYSTEM\\r\\n// ===================================================\\r\\n\\r\\nQLineEdit, QComboBox, QTextEdit {\\r\\n    background-color: $COLOR_BACKGROUND_2;\\r\\n    color: $COLOR_TEXT_1;\\r\\n    border: 1px solid $BORDER_COLOR;\\r\\n    border-radius: calc($CARD_RADIUS / 3);\\r\\n    padding: $SPACING_SM $SPACING_MD;\\r\\n    font-size: 14px;\\r\\n    margin-bottom: $SPACING_SM;\\r\\n    \\r\\n    &:focus {\\r\\n        border-color: $COLOR_ACCENT_1;\\r\\n        background-color: $COLOR_BACKGROUND_3;\\r\\n    }\\r\\n}\\r\\n\\r\\n// ===================================================\\r\\n// BUTTON VARIANTS\\r\\n// ===================================================\\r\\n\\r\\nQPushButton {\\r\\n    background-color: $COLOR_BACKGROUND_2;\\r\\n    color: $COLOR_TEXT_1;\\r\\n    border: 1px solid $BORDER_COLOR;\\r\\n    border-radius: calc($CARD_RADIUS / 2);\\r\\n    padding: $SPACING_SM $SPACING_MD;\\r\\n    font-weight: 500;\\r\\n    margin: $SPACING_SM;\\r\\n    \\r\\n    &:hover {\\r\\n        background-color: $COLOR_ACCENT_1;\\r\\n        color: $COLOR_BACKGROUND_1;\\r\\n    }\\r\\n}\\r\\n\\r\\nQPushButton#primaryButton {\\r\\n    background-color: $COLOR_ACCENT_1;\\r\\n    color: $COLOR_BACKGROUND_1;\\r\\n    font-weight: bold;\\r\\n}\\r\\n\\r\\nQPushButton#secondaryButton {\\r\\n    background-color: $CARD_BG;\\r\\n    color: $COLOR_TEXT_1;\\r\\n}\\r\\n\\r\\n// ===================================================\\r\\n// LAYOUT COMPONENTS\\r\\n// ===================================================\\r\\n\\r\\nQWidget#header {\\r\\n    background-color: $NAV_BG;\\r\\n    border-bottom: 1px solid $BORDER_COLOR;\\r\\n    padding: $SPACING_MD;\\r\\n}\\r\\n\\r\\nQWidget#footer {\\r\\n    background-color: $FOOTER_BG;\\r\\n    border-top: 1px solid $BORDER_COLOR;\\r\\n    padding: $SPACING_MD;\\r\\n}\\r\\n\\r\\nQWidget#sidebar {\\r\\n    background-color: $CARD_BG;\\r\\n    border-right: 1px solid $BORDER_COLOR;\\r\\n    padding: $SPACING_MD;\\r\\n}\\r\\n\\r\\n// ===================================================\\r\\n// UTILITY STYLES USING OBJECT NAMES\\r\\n// ===================================================\\r\\n\\r\\n// Text utilities\\r\\nQLabel#textTitle {\\r\\n    color: $COLOR_TEXT_1;\\r\\n    font-size: 18px;\\r\\n    font-weight: bold;\\r\\n    margin-bottom: $SPACING_MD;\\r\\n}\\r\\n\\r\\nQLabel#textSubtitle {\\r\\n    color: $COLOR_TEXT_2;\\r\\n    font-size: 14px;\\r\\n    margin-bottom: $SPACING_SM;\\r\\n}\\r\\n\\r\\nQLabel#textMuted {\\r\\n    color: $COLOR_TEXT_3;\\r\\n    font-size: 12px;\\r\\n}\\r\\n\\r\\n// Background utilities\\r\\nQWidget#bgCard {\\r\\n    background-color: $CARD_BG;\\r\\n    border-radius: $CARD_RADIUS;\\r\\n    padding: $SPACING_MD;\\r\\n}\\r\\n\\r\\nQWidget#bgNav {\\r\\n    background-color: $NAV_BG;\\r\\n}\\r\\n\\r\\nQWidget#bgFooter {\\r\\n    background-color: $FOOTER_BG;\\r\\n}\\r\\n\\r\\n// Border utilities\\r\\nQWidget#borderAll {\\r\\n    border: 1px solid $BORDER_COLOR;\\r\\n    border-radius: $CARD_RADIUS;\\r\\n}\\r\\n\\r\\nQWidget#borderBottom {\\r\\n    border-bottom: 1px solid $BORDER_COLOR;\\r\\n}\\r\\n\\r\\nQWidget#borderTop {\\r\\n    border-top: 1px solid $BORDER_COLOR;\\r\\n}\\r\\n```\\r\\n\\r\\n:::warning\\r\\n**Troubleshooting Tip**: If you encounter SCSS compilation errors when switching themes, check that all custom variables used in your QSS are defined in the currently active theme\'s `\\"Other-variables\\"` section.\\r\\n:::\\r\\n\\r\\n## Best Practices for Custom Variables\\r\\n\\r\\n### 1. Semantic Variable Names\\r\\nUse names that describe the purpose, not the value:\\r\\n```json\\r\\n\\"Other-variables\\": {\\r\\n    \\"CARD_RADIUS\\": \\"12px\\",           // Good\\r\\n    \\"HEADER_HEIGHT\\": \\"60px\\",         // Good\\r\\n    \\"PRIMARY_SPACING\\": \\"16px\\",       // Good\\r\\n    \\"blue_color\\": \\"#41cd52\\"          // Avoid - too specific\\r\\n}\\r\\n```\\r\\n\\r\\n### 2. Create a Design System\\r\\nDefine a consistent set of variables and ensure they exist in all themes:\\r\\n```json\\r\\n\\"Other-variables\\": {\\r\\n    // Spacing scale\\r\\n    \\"SPACING_XS\\": \\"4px\\",\\r\\n    \\"SPACING_SM\\": \\"8px\\", \\r\\n    \\"SPACING_MD\\": \\"16px\\",\\r\\n    \\"SPACING_LG\\": \\"24px\\",\\r\\n    \\"SPACING_XL\\": \\"32px\\",\\r\\n    \\r\\n    // Border radius scale\\r\\n    \\"RADIUS_SM\\": \\"4px\\",\\r\\n    \\"RADIUS_MD\\": \\"8px\\",\\r\\n    \\"RADIUS_LG\\": \\"12px\\",\\r\\n    \\"RADIUS_XL\\": \\"16px\\",\\r\\n    \\r\\n    // Component-specific\\r\\n    \\"CARD_BG\\": \\"#2c2c2c\\",\\r\\n    \\"NAV_BG\\": \\"#1e1e1e\\",\\r\\n    \\"HEADER_HEIGHT\\": \\"60px\\"\\r\\n}\\r\\n```\\r\\n\\r\\n:::tip\\r\\n**Consistency Tip**: Create a master list of your custom variables and use it as a checklist when adding new themes to ensure you don\'t miss any variables.\\r\\n:::\\r\\n\\r\\n### 3. Theme-Specific Adjustments\\r\\nYou can override variables for specific themes while keeping the same variable names:\\r\\n```json\\r\\n{\\r\\n  \\"Theme-name\\": \\"Qt-Light-Theme\\",\\r\\n  \\"Background-color\\": \\"#ffffff\\",\\r\\n  \\"Text-color\\": \\"#1e1e1e\\",\\r\\n  \\"Other-variables\\": {\\r\\n    \\"CARD_BG\\": \\"#f8f8f8\\",\\r\\n    \\"NAV_BG\\": \\"#f5f5f5\\",\\r\\n    \\"FOOTER_BG\\": \\"#e5e5e5\\",\\r\\n    \\"BORDER_COLOR\\": \\"rgba(65, 205, 82, 0.2)\\",\\r\\n    \\"HOVER_GLOW\\": \\"0 12px 32px rgba(65, 205, 82, 0.25)\\",\\r\\n    // Keep all other variables the same as other themes\\r\\n    \\"SPACING_SM\\": \\"8px\\",\\r\\n    \\"SPACING_MD\\": \\"16px\\",\\r\\n    \\"CARD_RADIUS\\": \\"12px\\"\\r\\n  }\\r\\n}\\r\\n```\\r\\n\\r\\n### 4. Using Variables in Python Code\\r\\nYou can also access these variables in your Python code:\\r\\n```python\\r\\nfrom Custom_Widgets.QAppSettings import QAppSettings\\r\\n\\r\\nclass MainWindow(QMainWindow):\\r\\n    def __init__(self):\\r\\n        super().__init__()\\r\\n        # Access theme variables\\r\\n        card_radius = self.theme.CARD_RADIUS\\r\\n        spacing_md = self.theme.SPACING_MD\\r\\n        \\r\\n        # Use in dynamic styling\\r\\n        self.ui.some_widget.setStyleSheet(f\\"\\"\\"\\r\\n            border-radius: {card_radius};\\r\\n            padding: {spacing_md};\\r\\n        \\"\\"\\")\\r\\n```\\r\\n\\r\\n:::warning\\r\\n**Development Note**: When adding new custom variables to your QSS, remember to update all themes in your JSON file with the new variables to prevent theme switching errors.\\r\\n:::\\r\\n\\r\\n## Benefits of Using Custom Variables\\r\\n\\r\\n1. **Consistency**: Ensure visual consistency across your application\\r\\n2. **Maintainability**: Change values in one place to update everywhere\\r\\n3. **Theme Cohesion**: Custom variables work seamlessly with theme switching\\r\\n4. **Developer Experience**: Clear, semantic variable names improve code readability\\r\\n5. **Scalability**: Easy to add new components that follow the same design system\\r\\n\\r\\nBy leveraging custom variables in your JSON themes, you create a robust, maintainable styling system that scales with your application and provides a consistent user experience across different themes."},{"id":"getting-started-with-qt-custom-widgets","metadata":{"permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/getting-started-with-qt-custom-widgets","editUrl":"https://github.com/SpinnCompany/Docs-QT-PyQt-PySide-Custom-Widgets/tree/main/blog/2025-11-12-getting-started-with-qt-custom-widgets.md","source":"@site/blog/2025-11-12-getting-started-with-qt-custom-widgets.md","title":"Getting Started With Qt Custom Widgets","description":"Step 1: Install Python and Create Virtual Environment","date":"2025-11-12T00:00:00.000Z","tags":[{"inline":true,"label":"PySide6","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/py-side-6"},{"inline":true,"label":"Python","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/python"},{"inline":true,"label":"GUI","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/gui"},{"inline":true,"label":"Custom Widgets","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/custom-widgets"},{"inline":true,"label":"Tutorial","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/tutorial"},{"inline":true,"label":"Qt","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/qt"},{"inline":true,"label":"PyQt","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/py-qt"},{"inline":true,"label":"Gui. Interface","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/gui-interface"},{"inline":true,"label":"Desktop","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/desktop"}],"readingTime":7.54,"hasTruncateMarker":false,"authors":[{"name":"Khamisi Kibet","title":"Creator of Qt Custom Widgets","url":"https://github.com/khamisikibet","email":"khamisikibet@gmail.com","imageURL":"https://github.com/khamisikibet.png","key":"Khamisi Kibet","page":null}],"frontMatter":{"authors":["Khamisi Kibet"],"date":"2025-11-12","slug":"getting-started-with-qt-custom-widgets","tags":["PySide6","Python","GUI","Custom Widgets","Tutorial","Qt","PyQt","Gui. Interface","Desktop"],"title":"Getting Started With Qt Custom Widgets"},"unlisted":false,"prevItem":{"title":"Custom Variables in JSon and QSS Style Sheets","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/custom-variables-in-json-and-qss-style-sheets"},"nextItem":{"title":"Qt Theme Styling Guide: Json Stylesheet","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/qt-theme-styling-guide-json-stylesheet"}},"content":"## Step 1: Install Python and Create Virtual Environment\\r\\n\\r\\n### Install Python\\r\\nFirst, ensure you have Python 3.7 or higher installed:\\r\\n\\r\\n**Windows:**\\r\\n```bash\\r\\n# Download from python.org or use winget\\r\\nwinget install Python.Python.3.11\\r\\n```\\r\\n\\r\\n**macOS:**\\r\\n```bash\\r\\n# Using Homebrew\\r\\nbrew install python\\r\\n```\\r\\n\\r\\n**Linux (Ubuntu/Debian):**\\r\\n```bash\\r\\nsudo apt update\\r\\nsudo apt install python3 python3-pip python3-venv\\r\\n```\\r\\n\\r\\n### Create Virtual Environment\\r\\nAlways use a virtual environment to manage dependencies:\\r\\n\\r\\n```bash\\r\\n# Create project directory\\r\\nmkdir my_qt_project\\r\\ncd my_qt_project\\r\\n\\r\\n# Create virtual environment\\r\\npython -m venv venv\\r\\n\\r\\n# Activate virtual environment\\r\\n# Windows:\\r\\nvenv\\\\Scripts\\\\activate\\r\\n# macOS/Linux:\\r\\nsource venv/bin/activate\\r\\n```\\r\\n\\r\\nYour terminal should now show `(venv)` indicating the virtual environment is active.\\r\\n\\r\\n---\\r\\n\\r\\n## Step 2: Install Qt Binding\\r\\n\\r\\n**Important:** Make sure your virtual environment is activated (you see `(venv)` in your terminal).\\r\\n\\r\\nChoose and install one of these Qt bindings:\\r\\n\\r\\n### Option 1: PySide6 (Recommended)\\r\\n```bash\\r\\npip install PySide6\\r\\n```\\r\\n\\r\\n### Option 2: PyQt6\\r\\n```bash\\r\\npip install PyQt6\\r\\n```\\r\\n\\r\\n### Option 3: PySide2\\r\\n```bash\\r\\npip install PySide2\\r\\n```\\r\\n\\r\\n### Option 4: PyQt5\\r\\n```bash\\r\\npip install PyQt5\\r\\n```\\r\\n\\r\\n**Note:** For this tutorial, we\'ll use PySide6 as it\'s the most modern and freely available.\\r\\n\\r\\n---\\r\\n\\r\\n## Step 3: Install Custom Widgets\\r\\n\\r\\nInstall the custom widgets package (make sure venv is active):\\r\\n\\r\\n```bash\\r\\npip install QT-PyQt-PySide-Custom-Widgets\\r\\n```\\r\\n\\r\\nVerify installation:\\r\\n```bash\\r\\npython -c \\"import Custom_Widgets; print(\'Custom Widgets installed successfully!\')\\"\\r\\n```\\r\\n\\r\\n---\\r\\n\\r\\n## Step 4: Create Your First Project\\r\\n\\r\\n### Method A: Using the Project Creator (Recommended for Beginners)\\r\\n\\r\\n**Important:** Run this command from INSIDE your activated virtual environment folder:\\r\\n\\r\\n```bash\\r\\n# You should be in your project directory with venv activated\\r\\n# Your terminal should show: (venv) path/to/your/project$\\r\\n\\r\\n# Run project creator FROM INSIDE THE VENV FOLDER\\r\\nCustom_Widgets --create-project\\r\\n```\\r\\n\\r\\n**What happens when you run the project creator:**\\r\\n1. It detects your current directory as the project location\\r\\n2. It checks if the folder is empty (or only contains logs)\\r\\n3. It guides you through the setup process interactively\\r\\n\\r\\nThe project creator will guide you through:\\r\\n1. **Qt Binding Selection**: Choose your Qt library\\r\\n2. **Color Scheme**: Select icons and theme colors\\r\\n3. **App Information**: Enter app name and organization details\\r\\n4. **Automatic Setup**: Creates all necessary files and folders\\r\\n\\r\\n### Correct Folder Structure Example:\\r\\n```\\r\\nmy_qt_project/          # Your project folder\\r\\n\u251c\u2500\u2500 venv/               # Virtual environment (already created)\\r\\n\u2502   \u251c\u2500\u2500 bin/            # or Scripts/ on Windows\\r\\n\u2502   \u251c\u2500\u2500 lib/\\r\\n\u2502   \u2514\u2500\u2500 pyvenv.cfg\\r\\n\u2514\u2500\u2500 (project files will be created here by the creator)\\r\\n```\\r\\n\\r\\n**Common Mistake to Avoid:**\\r\\n- Don\'t run the command from inside the `venv` folder\\r\\n- Run it from your project root folder where `venv` is located\\r\\n\\r\\n### Method B: Manual Setup (For Advanced Users)\\r\\nIf you prefer manual setup, create this structure in your project root:\\r\\n```\\r\\nmy_qt_project/\\r\\n\u251c\u2500\u2500 venv/               # Virtual environment\\r\\n\u251c\u2500\u2500 main.py             # Main application file\\r\\n\u251c\u2500\u2500 ui/                 # UI files directory\\r\\n\u2502   \u2514\u2500\u2500 main_window.ui\\r\\n\u251c\u2500\u2500 json-styles/        # Theme configuration\\r\\n\u2502   \u2514\u2500\u2500 style.json\\r\\n\u251c\u2500\u2500 requirements.txt    # Dependencies\\r\\n\u2514\u2500\u2500 README.md          # Documentation\\r\\n```\\r\\n\\r\\n---\\r\\n\\r\\n## Step 5: Understanding the Project Structure\\r\\n\\r\\nAfter running the project creator from inside your venv folder, you\'ll have:\\r\\n\\r\\n```\\r\\nmy_qt_project/\\r\\n\u251c\u2500\u2500 venv/               # Virtual environment\\r\\n\u251c\u2500\u2500 main.py              # Main application file\\r\\n\u251c\u2500\u2500 ui/                  # UI files directory\\r\\n\u2502   \u2514\u2500\u2500 QCustomQMainWindow.ui\\r\\n\u251c\u2500\u2500 json-styles/         # Theme configuration\\r\\n\u2502   \u2514\u2500\u2500 style.json\\r\\n\u251c\u2500\u2500 requirements.txt     # Dependencies\\r\\n\u2514\u2500\u2500 README.md           # Documentation\\r\\n```\\r\\n\\r\\n---\\r\\n\\r\\n## Step 6: Register Custom Widgets with Qt Designer\\r\\n\\r\\nBefore designing your interface, register the custom widgets (from your activated venv):\\r\\n\\r\\n```bash\\r\\n# Register widgets with Qt Designer\\r\\nCustom_Widgets --register-widgets\\r\\n```\\r\\n\\r\\n**Expected Output:**\\r\\n```\\r\\nRegistering QCustomQMainWindow...\\r\\nRegistering QCustomSidebar...\\r\\nRegistering QCustomProgressBar...\\r\\n... (all widgets registered successfully)\\r\\n```\\r\\n\\r\\n---\\r\\n\\r\\n## Step 7: Launch Qt Designer with Custom Widgets\\r\\n\\r\\nStart Qt Designer with the custom widgets loaded (from activated venv):\\r\\n\\r\\n```bash\\r\\n# Launch Qt Designer with custom widgets\\r\\nCustom_Widgets --start-designer --plugins\\r\\n```\\r\\n\\r\\n**Alternative methods:**\\r\\n```bash\\r\\n# If the above doesn\'t work, try:\\r\\ndesigner\\r\\n# or\\r\\npyside6-designer\\r\\n# or\\r\\nqt5-designer\\r\\n```\\r\\n\\r\\n---\\r\\n\\r\\n## Step 8: Designing Your Interface in Qt Designer\\r\\n\\r\\n### Finding Custom Widgets\\r\\nWhen Qt Designer opens, look for these widget groups in the widget box:\\r\\n\\r\\n1. **MainWindow Section**:\\r\\n   - `QCustomQMainWindow` - Enhanced main window with theme support\\r\\n\\r\\n2. **Sidebar Section**:\\r\\n   - `QCustomSidebar` - Customizable sidebar navigation\\r\\n   - `QCustomSidebarButton` - Buttons for sidebar\\r\\n   - `QCustomSidebarLabel` - Labels for sidebar\\r\\n\\r\\n3. **Progressbars Section**:\\r\\n   - `QCustomRoundProgressBar` - Circular progress indicator\\r\\n   - `AnalogGaugeWidget` - Analog gauge display\\r\\n\\r\\n4. **Component Container Section**:\\r\\n   - `QCustomComponent` - Container for organizing widgets\\r\\n   - `QCustomComponentContainer` - Main container component\\r\\n\\r\\n### Step-by-Step Design Process\\r\\n\\r\\n1. **Start with QCustomQMainWindow**:\\r\\n   - Drag `QCustomQMainWindow` from the widget box to the form\\r\\n   - This becomes your main application window\\r\\n\\r\\n2. **Add a Sidebar**:\\r\\n   - Drag `QCustomSidebar` to the left side of your main window\\r\\n   - Add `QCustomSidebarButton` widgets inside the sidebar\\r\\n   - Set button text and icons in the property editor\\r\\n\\r\\n3. **Add Content Area**:\\r\\n   - Use `QCustomComponent` as content containers\\r\\n   - Add standard Qt widgets (buttons, labels, etc.) inside components\\r\\n   - Use `QCustomQStackedWidget` to manage multiple pages\\r\\n\\r\\n4. **Style Your Interface**:\\r\\n   - Use the property editor to set object names\\r\\n   - Apply custom styles through the JSON configuration later\\r\\n\\r\\n5. **Save Your Design**:\\r\\n   - Save the file as `main_window.ui` in the `ui/` folder\\r\\n   - Qt Designer files use `.ui` extension\\r\\n\\r\\n---\\r\\n\\r\\n## Step 9: Automatic UI File Conversion\\r\\n\\r\\n### Start File Monitoring (Recommended)\\r\\nKeep this running while you design (from activated venv):\\r\\n\\r\\n```bash\\r\\n# Monitor UI folder for changes\\r\\nCustom_Widgets --monitor-ui ui --qt-library PySide6\\r\\n```\\r\\n\\r\\n**What this does:**\\r\\n- Watches the `ui/` folder for any changes\\r\\n- Automatically converts `.ui` files to Python when you save\\r\\n- Updates your application in real-time\\r\\n\\r\\n### Manual Conversion\\r\\nIf you prefer manual conversion:\\r\\n\\r\\n```bash\\r\\n# Convert specific file\\r\\nCustom_Widgets --convert-ui ui/main_window.ui --qt-library PySide6\\r\\n\\r\\n# Convert all files in folder\\r\\nCustom_Widgets --convert-ui ui --qt-library PySide6\\r\\n```\\r\\n\\r\\n---\\r\\n\\r\\n## Step 10: Customize Your App Theme\\r\\n\\r\\nEdit the `json-styles/style.json` file to customize your app\'s appearance:\\r\\n\\r\\n```json\\r\\n{\\r\\n    \\"QtBinding\\": \\"PySide6\\",\\r\\n    \\"QMainWindow\\": {\\r\\n        \\"title\\": \\"My Awesome App\\"\\r\\n    },\\r\\n    \\"QSettings\\": {\\r\\n        \\"AppSettings\\": {\\r\\n            \\"OrginizationName\\": \\"My Company\\",\\r\\n            \\"ApplicationName\\": \\"My App\\",\\r\\n            \\"OrginizationDormain\\": \\"myapp.org\\"\\r\\n        },\\r\\n        \\"ThemeSettings\\": {\\r\\n            \\"QtDesignerIconsColor\\": \\"#ffffff\\",\\r\\n            \\"CustomThemes\\": [\\r\\n                {\\r\\n                    \\"Background-color\\": \\"#2b2b2b\\",\\r\\n                    \\"Text-color\\": \\"#ffffff\\",\\r\\n                    \\"Accent-color\\": \\"#0078d4\\",\\r\\n                    \\"Icons-color\\": \\"#ffffff\\",\\r\\n                    \\"Theme-name\\": \\"Default Dark\\",\\r\\n                    \\"Default-Theme\\": true\\r\\n                }\\r\\n            ]\\r\\n        }\\r\\n    }\\r\\n}\\r\\n```\\r\\n\\r\\n**Key Configuration Options:**\\r\\n- `Background-color`: Main app background\\r\\n- `Text-color`: Default text color\\r\\n- `Accent-color`: Primary accent color for buttons, highlights\\r\\n- `Icons-color`: Color of all icons in the app\\r\\n\\r\\n---\\r\\n\\r\\n## Step 11: Run Your Application\\r\\n\\r\\nExecute your application (from activated venv):\\r\\n\\r\\n```bash\\r\\npython main.py\\r\\n```\\r\\n\\r\\nYour custom-styled application should launch with:\\r\\n- The theme colors you configured\\r\\n- All custom widgets functioning\\r\\n- Your designed interface layout\\r\\n\\r\\n---\\r\\n\\r\\n## Step 12: Development Workflow Tips\\r\\n\\r\\n### Efficient Development Cycle\\r\\n1. **Activate Venv**: Always start with `source venv/bin/activate` (or `venv\\\\Scripts\\\\activate` on Windows)\\r\\n2. **Design**: Work in Qt Designer with custom widgets\\r\\n3. **Save**: Save your `.ui` file (auto-conversion happens if monitoring)\\r\\n4. **Test**: Run your app to see changes\\r\\n5. **Repeat**: Go back to design and continue iterating\\r\\n\\r\\n### Useful Commands for Daily Use (Run from activated venv)\\r\\n```bash\\r\\n# Start monitoring when beginning work\\r\\nCustom_Widgets --monitor-ui ui --qt-library PySide6\\r\\n\\r\\n# Launch designer when needed\\r\\nCustom_Widgets --start-designer --plugins\\r\\n\\r\\n# Run your app\\r\\npython main.py\\r\\n```\\r\\n\\r\\n### Complete Workflow Example\\r\\n```bash\\r\\n# 1. Start fresh each day\\r\\ncd my_qt_project\\r\\nsource venv/bin/activate  # or venv\\\\Scripts\\\\activate on Windows\\r\\n\\r\\n# 2. Start file monitoring (keep this terminal open)\\r\\nCustom_Widgets --monitor-ui ui --qt-library PySide6\\r\\n\\r\\n# 3. In another terminal, launch designer\\r\\ncd my_qt_project\\r\\nsource venv/bin/activate\\r\\nCustom_Widgets --start-designer --plugins\\r\\n\\r\\n# 4. When ready to test\\r\\npython main.py\\r\\n```\\r\\n\\r\\n---\\r\\n\\r\\n## Step 13: Advanced Customization\\r\\n\\r\\n### Creating Multiple Themes\\r\\nAdd additional themes to your `style.json`:\\r\\n\\r\\n```json\\r\\n\\"CustomThemes\\": [\\r\\n    {\\r\\n        \\"Background-color\\": \\"#2b2b2b\\",\\r\\n        \\"Text-color\\": \\"#ffffff\\",\\r\\n        \\"Accent-color\\": \\"#0078d4\\",\\r\\n        \\"Icons-color\\": \\"#ffffff\\",\\r\\n        \\"Theme-name\\": \\"Dark Blue\\",\\r\\n        \\"Default-Theme\\": true\\r\\n    },\\r\\n    {\\r\\n        \\"Background-color\\": \\"#f0f0f0\\",\\r\\n        \\"Text-color\\": \\"#000000\\",\\r\\n        \\"Accent-color\\": \\"#e74c3c\\",\\r\\n        \\"Icons-color\\": \\"#000000\\",\\r\\n        \\"Theme-name\\": \\"Light Red\\",\\r\\n        \\"Default-Theme\\": false\\r\\n    }\\r\\n]\\r\\n```\\r\\n\\r\\n### Custom Widget Properties\\r\\nEach custom widget has specific properties you can set in Qt Designer:\\r\\n\\r\\n- **QCustomSidebar**: `backgroundColor`, `activeColor`, `iconSize`\\r\\n- **QCustomProgressBar**: `progressColor`, `background_color`, `text_color`\\r\\n- **QCustomQMainWindow**: `enableCustomTitleBar`, `enableGradient`\\r\\n\\r\\n---\\r\\n\\r\\n## Troubleshooting Common Issues\\r\\n\\r\\n### Virtual Environment Issues\\r\\n```bash\\r\\n# Check if venv is activated\\r\\nwhich python  # Should point to venv directory\\r\\n\\r\\n# If not activated:\\r\\nsource venv/bin/activate  # macOS/Linux\\r\\nvenv\\\\Scripts\\\\activate     # Windows\\r\\n```\\r\\n\\r\\n### Widgets Not Showing in Qt Designer\\r\\n```bash\\r\\n# Re-register widgets (from activated venv)\\r\\nCustom_Widgets --register-widgets\\r\\n\\r\\n# Restart Qt Designer\\r\\nCustom_Widgets --start-designer --plugins\\r\\n```\\r\\n\\r\\n### UI Files Not Converting\\r\\n```bash\\r\\n# Check if monitoring is running (from activated venv)\\r\\nCustom_Widgets --monitor-ui ui --qt-library PySide6\\r\\n\\r\\n# Manual conversion (from activated venv)\\r\\nCustom_Widgets --convert-ui ui/main_window.ui --qt-library PySide6\\r\\n```\\r\\n\\r\\n### Import Errors\\r\\n```bash\\r\\n# Ensure package is installed in venv\\r\\npip install QT-PyQt-PySide-Custom-Widgets\\r\\n\\r\\n# Check virtual environment is activated\\r\\nwhich python  # Should point to venv directory\\r\\n```\\r\\n\\r\\n### Project Creator Not Working\\r\\n```bash\\r\\n# Make sure you\'re in the correct directory\\r\\npwd  # Should show your project folder, not inside venv\\r\\n\\r\\n# Check folder contents\\r\\nls -la  # Should show venv folder and your project files\\r\\n\\r\\n# If you accidentally ran creator in wrong location:\\r\\n# Delete the generated files and run again from correct location\\r\\n```\\r\\n\\r\\n---\\r\\n\\r\\n## Next Steps\\r\\n\\r\\nNow that you have a basic application running:\\r\\n\\r\\n1. **Explore More Widgets**: Try different custom widgets in your designs\\r\\n2. **Custom Styles**: Experiment with different color schemes in the JSON file\\r\\n3. **Advanced Layouts**: Combine custom widgets with standard Qt widgets\\r\\n4. **Animation**: Add transitions and animations to your interface\\r\\n5. **Database Integration**: Connect your GUI to databases or APIs\\r\\n\\r\\n## Resources\\r\\n\\r\\n- **Documentation**: [GitHub Repository](https://github.com/KhamisiKibet/Qt-PyQt-PySide-Custom-Widgets)\\r\\n- **Video Tutorials**: [SPINN TV YouTube Channel](https://www.youtube.com/spinnTv)\\r\\n- **Community Support**: GitHub Issues and Discussions\\r\\n\\r\\n---\\r\\n\\r\\n**Congratulations!** You\'ve successfully set up a Qt application with custom widgets using proper virtual environment practices. The automated workflow will make your development process much smoother as you continue building your application.\\r\\n\\r\\n**Key Takeaway:** Always remember to activate your virtual environment before running any Custom_Widgets commands or your Python application!"},{"id":"qt-theme-styling-guide-json-stylesheet","metadata":{"permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/qt-theme-styling-guide-json-stylesheet","editUrl":"https://github.com/SpinnCompany/Docs-QT-PyQt-PySide-Custom-Widgets/tree/main/blog/2025-11-12-qt-theme-styling-guide-json-stylesheet.md","source":"@site/blog/2025-11-12-qt-theme-styling-guide-json-stylesheet.md","title":"Qt Theme Styling Guide: Json Stylesheet","description":"In this guide, we\'ll walk through creating professional Qt Dark and Light themes for your custom widgets applications. These themes follow Qt\'s design language while providing modern, visually appealing interfaces.","date":"2025-11-12T00:00:00.000Z","tags":[{"inline":true,"label":"PySide6","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/py-side-6"},{"inline":true,"label":"Python","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/python"},{"inline":true,"label":"GUI","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/gui"},{"inline":true,"label":"Custom Widgets","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/custom-widgets"},{"inline":true,"label":"Tutorial","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/tutorial"},{"inline":true,"label":"version","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/version"},{"inline":true,"label":"news","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/news"}],"readingTime":3.97,"hasTruncateMarker":false,"authors":[{"name":"Khamisi Kibet","title":"Creator of Qt Custom Widgets","url":"https://github.com/khamisikibet","email":"khamisikibet@gmail.com","imageURL":"https://github.com/khamisikibet.png","key":"Khamisi Kibet","page":null}],"frontMatter":{"authors":["Khamisi Kibet"],"date":"2025-11-12","slug":"qt-theme-styling-guide-json-stylesheet","tags":["PySide6","Python","GUI","Custom Widgets","Tutorial","version","news"],"title":"Qt Theme Styling Guide: Json Stylesheet"},"unlisted":false,"prevItem":{"title":"Getting Started With Qt Custom Widgets","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/getting-started-with-qt-custom-widgets"},"nextItem":{"title":"Qt Theme Styling Guide: Qss/Css Stylesheet","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/qt-theme-styling-guide-qsscss-stylesheet"}},"content":"In this guide, we\'ll walk through creating professional Qt Dark and Light themes for your custom widgets applications. These themes follow Qt\'s design language while providing modern, visually appealing interfaces.\\r\\n\\r\\n## Theme Color Palettes\\r\\n\\r\\n### Qt Dark Theme Colors\\r\\n- **Background**: `#1e1e1e` (Dark gray)\\r\\n- **Text**: `#e0e0e0` (Light gray)\\r\\n- **Accent**: `#41cd52` (Qt green)\\r\\n- **Icons**: `#41cd52` (Qt green)\\r\\n- **Cards**: `#2c2c2c` (Slightly lighter dark gray)\\r\\n- **Footer**: `#111111` (Near black)\\r\\n\\r\\n### Qt Light Theme Colors  \\r\\n- **Background**: `#ffffff` (Pure white)\\r\\n- **Text**: `#1e1e1e` (Dark gray)\\r\\n- **Accent**: `#41cd52` (Qt green)\\r\\n- **Icons**: `#41cd52` (Qt green)\\r\\n- **Cards**: `#f8f8f8` (Off-white)\\r\\n- **Footer**: `#e5e5e5` (Light gray)\\r\\n\\r\\n## Complete Theme Configuration\\r\\n\\r\\nHere\'s how to implement both themes in your `style.json`:\\r\\n\\r\\n```json\\r\\n{\\r\\n  \\"QSettings\\": [\\r\\n    {\\r\\n      \\"ThemeSettings\\": {\\r\\n        \\"QtDesignerIconsColor\\": \\"#41CD52\\",\\r\\n        \\"CustomThemes\\": [\\r\\n          {\\r\\n            \\"Theme-name\\": \\"Qt-Dark-Theme\\",\\r\\n            \\"Background-color\\": \\"#1e1e1e\\",\\r\\n            \\"Text-color\\": \\"#e0e0e0\\",\\r\\n            \\"Accent-color\\": \\"#41cd52\\",\\r\\n            \\"Icons-color\\": \\"#41cd52\\",\\r\\n            \\"Default-Theme\\": true,\\r\\n            \\"Create-icons\\": true,\\r\\n            \\"Other-variables\\": {\\r\\n              \\"CARD_RADIUS\\": \\"12px\\",\\r\\n              \\"FOOTER_BG\\": \\"#111111\\",\\r\\n              \\"NAV_BG\\": \\"#1e1e1e\\",\\r\\n              \\"CARD_BG\\": \\"#2c2c2c\\",\\r\\n              \\"BORDER_COLOR\\": \\"rgba(65, 205, 82, 0.3)\\",\\r\\n              \\"HOVER_GLOW\\": \\"0 12px 32px rgba(65, 205, 82, 0.45)\\",\\r\\n              \\"GRADIENT\\": \\"linear-gradient(135deg, #41cd52, #2fa440)\\"\\r\\n            }\\r\\n          },\\r\\n          {\\r\\n            \\"Theme-name\\": \\"Qt-Light-Theme\\",\\r\\n            \\"Background-color\\": \\"#ffffff\\",\\r\\n            \\"Text-color\\": \\"#1e1e1e\\",\\r\\n            \\"Accent-color\\": \\"#41cd52\\",\\r\\n            \\"Icons-color\\": \\"#41cd52\\",\\r\\n            \\"Default-Theme\\": false,\\r\\n            \\"Create-icons\\": true,\\r\\n            \\"Other-variables\\": {\\r\\n              \\"CARD_RADIUS\\": \\"12px\\",\\r\\n              \\"FOOTER_BG\\": \\"#e5e5e5\\",\\r\\n              \\"NAV_BG\\": \\"#f5f5f5\\",\\r\\n              \\"CARD_BG\\": \\"#f8f8f8\\",\\r\\n              \\"BORDER_COLOR\\": \\"rgba(65, 205, 82, 0.2)\\",\\r\\n              \\"HOVER_GLOW\\": \\"0 12px 32px rgba(65, 205, 82, 0.25)\\",\\r\\n              \\"GRADIENT\\": \\"linear-gradient(135deg, #41cd52, #2fa440)\\"\\r\\n            }\\r\\n          }\\r\\n        ]\\r\\n      }\\r\\n    }\\r\\n  ]\\r\\n}\\r\\n```\\r\\n\\r\\n## Key Design Principles\\r\\n\\r\\n### 1. Color Contrast\\r\\n- **Dark Theme**: High contrast between background (`#1e1e1e`) and text (`#e0e0e0`)\\r\\n- **Light Theme**: Strong contrast between background (`#ffffff`) and text (`#1e1e1e`)\\r\\n- **Accessibility**: Both themes maintain WCAG AA compliance for text readability\\r\\n\\r\\n### 2. Consistent Accent Color\\r\\n- Uses Qt\'s signature green (`#41cd52`) across both themes\\r\\n- Provides visual consistency when switching between themes\\r\\n- Green color represents Qt\'s brand identity\\r\\n\\r\\n### 3. Layered Backgrounds\\r\\n- **Dark Theme**: Three levels of darkness for depth\\r\\n- **Light Theme**: Three levels of lightness for hierarchy\\r\\n- Each layer serves a specific purpose in the UI\\r\\n\\r\\n### 4. Modern Effects\\r\\n- **Border Radius**: Consistent 12px rounded corners\\r\\n- **Shadows**: Theme-appropriate glow effects\\r\\n- **Gradients**: Subtle green gradients for visual interest\\r\\n\\r\\n## Theme Variables Explained\\r\\n\\r\\n### Core Colors\\r\\n- `Background-color`: Main application background\\r\\n- `Text-color`: Primary text color for readability  \\r\\n- `Accent-color`: Primary brand color for interactive elements\\r\\n- `Icons-color`: Color for all icon assets\\r\\n\\r\\n### Additional Variables\\r\\n- `CARD_RADIUS`: Border radius for cards and containers\\r\\n- `FOOTER_BG`: Background color for footer areas\\r\\n- `NAV_BG`: Background for navigation elements\\r\\n- `CARD_BG`: Background for card components\\r\\n- `BORDER_COLOR`: Border colors with theme-appropriate opacity\\r\\n- `HOVER_GLOW`: Shadow effects for interactive states\\r\\n- `GRADIENT`: CSS gradients for visual enhancements\\r\\n\\r\\n## Implementation Tips\\r\\n\\r\\n### 1. Setting Default Theme\\r\\n```json\\r\\n\\"Default-Theme\\": true\\r\\n```\\r\\nSet this to `true` for your preferred default theme. The other theme should have `false`.\\r\\n\\r\\n### 2. Icon Generation\\r\\n```json\\r\\n\\"Create-icons\\": true\\r\\n```\\r\\nThis ensures icons are automatically generated in your theme colors.\\r\\n\\r\\n### 3. Opacity Adjustments\\r\\nNotice how border colors use rgba with different opacity:\\r\\n- Dark theme: `rgba(65, 205, 82, 0.3)` (more visible)\\r\\n- Light theme: `rgba(65, 205, 82, 0.2)` (more subtle)\\r\\n\\r\\n### 4. Shadow Intensity\\r\\n- Dark theme shadows are more pronounced (`0.45` opacity)\\r\\n- Light theme shadows are more subtle (`0.25` opacity)\\r\\n\\r\\n## Theme Switching\\r\\n\\r\\nTo implement theme switching in your application:\\r\\n\\r\\n1. Set one theme as default with `\\"Default-Theme\\": true`\\r\\n2. Use the other theme for the alternative mode\\r\\n3. Implement a toggle mechanism in your UI\\r\\n4. Reload the theme configuration when switching\\r\\n\\r\\n## Benefits of This Approach\\r\\n\\r\\n### 1. Brand Consistency\\r\\n- Maintains Qt\'s visual identity with the green accent color\\r\\n- Professional appearance suitable for commercial applications\\r\\n\\r\\n### 2. User Experience\\r\\n- Dark theme reduces eye strain in low-light environments\\r\\n- Light theme provides familiarity for traditional desktop apps\\r\\n- Smooth transitions between themes\\r\\n\\r\\n### 3. Developer Experience\\r\\n- Clear variable naming makes customization easy\\r\\n- Consistent design tokens across all components\\r\\n- Easy to extend with additional color variations\\r\\n\\r\\n### 4. Performance\\r\\n- Efficient color scheme with minimal variables\\r\\n- Optimized for both dark and light mode rendering\\r\\n\\r\\n## Customization Examples\\r\\n\\r\\n### Changing Accent Color\\r\\nTo use a different accent color, simply replace all instances of `#41cd52` with your preferred color:\\r\\n\\r\\n```json\\r\\n\\"Accent-color\\": \\"#0078d4\\",\\r\\n\\"Icons-color\\": \\"#0078d4\\",\\r\\n\\"QtDesignerIconsColor\\": \\"#0078d4\\"\\r\\n```\\r\\n\\r\\n### Adjusting Contrast\\r\\nFor higher contrast in the dark theme:\\r\\n```json\\r\\n\\"Background-color\\": \\"#121212\\",\\r\\n\\"Text-color\\": \\"#ffffff\\"\\r\\n```\\r\\n\\r\\n### Modifying Border Radius\\r\\nFor softer or sharper corners:\\r\\n```json\\r\\n\\"CARD_RADIUS\\": \\"8px\\"  // Softer\\r\\n\\"CARD_RADIUS\\": \\"16px\\" // Rounder\\r\\n```\\r\\n\\r\\n## Conclusion\\r\\n\\r\\nThese Qt Dark and Light themes provide a solid foundation for creating professional applications with custom widgets. The color schemes are carefully chosen to be both aesthetically pleasing and functionally effective, following modern design principles while staying true to Qt\'s visual identity.\\r\\n\\r\\nRemember to test your themes in different lighting conditions and consider user preferences when deciding which theme to set as default. The flexibility of this system allows you to easily create additional theme variations or customize the existing ones to match your specific application needs.\\r\\n\\r\\nFor more advanced theming options, refer to the Custom Widgets documentation on GitHub and explore additional styling variables available for specific widget types."},{"id":"qt-theme-styling-guide-qsscss-stylesheet","metadata":{"permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/qt-theme-styling-guide-qsscss-stylesheet","editUrl":"https://github.com/SpinnCompany/Docs-QT-PyQt-PySide-Custom-Widgets/tree/main/blog/2025-11-12-qt-theme-styling-guide-qsscss-stylesheet.md","source":"@site/blog/2025-11-12-qt-theme-styling-guide-qsscss-stylesheet.md","title":"Qt Theme Styling Guide: Qss/Css Stylesheet","description":"This guide explains how to use the auto-generated theme variables in your QSS/SCSS files to create dynamic, theme-aware styles for your Qt applications.","date":"2025-11-12T00:00:00.000Z","tags":[{"inline":true,"label":"PySide6","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/py-side-6"},{"inline":true,"label":"Python","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/python"},{"inline":true,"label":"GUI","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/gui"},{"inline":true,"label":"Custom Widgets","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/custom-widgets"},{"inline":true,"label":"Tutorial","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/tutorial"}],"readingTime":3.16,"hasTruncateMarker":false,"authors":[{"name":"Khamisi Kibet","title":"Creator of Qt Custom Widgets","url":"https://github.com/khamisikibet","email":"khamisikibet@gmail.com","imageURL":"https://github.com/khamisikibet.png","key":"Khamisi Kibet","page":null}],"frontMatter":{"authors":["Khamisi Kibet"],"date":"2025-11-12","slug":"qt-theme-styling-guide-qsscss-stylesheet","tags":["PySide6","Python","GUI","Custom Widgets","Tutorial"],"title":"Qt Theme Styling Guide: Qss/Css Stylesheet"},"unlisted":false,"prevItem":{"title":"Qt Theme Styling Guide: Json Stylesheet","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/qt-theme-styling-guide-json-stylesheet"},"nextItem":{"title":"V 2.0.1 Released","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/v-201-released"}},"content":"This guide explains how to use the auto-generated theme variables in your QSS/SCSS files to create dynamic, theme-aware styles for your Qt applications.\\r\\n\\r\\n## Understanding Auto-Generated Theme Variables\\r\\n\\r\\nWhen you define themes in your `style.json` file, the Custom Widgets system automatically generates SCSS variables that you can use throughout your stylesheets. These variables are created based on your theme colors and custom variables.\\r\\n\\r\\n### Core Color Variables\\r\\n\\r\\nThe system generates a comprehensive color palette from your base theme colors:\\r\\n\\r\\n- **Background colors**: `$COLOR_BACKGROUND_1` through `$COLOR_BACKGROUND_6` (6 shades from light to dark)\\r\\n- **Text colors**: `$COLOR_TEXT_1` through `$COLOR_TEXT_4` (4 shades from light to dark)  \\r\\n- **Accent colors**: `$COLOR_ACCENT_1` through `$COLOR_ACCENT_4` (4 shades from light to dark)\\r\\n- **RGB components**: Individual RGB values for each color (e.g., `$CB1_R`, `$CB1_G`, `$CB1_B` for background colors)\\r\\n\\r\\n### Additional Generated Variables\\r\\n\\r\\n- **Borders**: Pre-defined border styles (`$BORDER_1`, `$BORDER_2`, `$BORDER_3`)\\r\\n- **Selection borders**: Accent-colored borders (`$BORDER_SELECTION_1`, etc.)\\r\\n- **Border radius**: `$SIZE_BORDER_RADIUS`\\r\\n- **Tooltip opacity**: `$OPACITY_TOOLTIP`\\r\\n- **Resource paths**: `$PATH_RESOURCES`, `$RELATIVE_FOLDER`\\r\\n\\r\\n### Custom Theme Variables\\r\\n\\r\\nVariables defined in your JSON theme under `\\"Other-variables\\"` are also available:\\r\\n\\r\\n```json\\r\\n\\"Other-variables\\": {\\r\\n  \\"CARD_RADIUS\\": \\"12px\\",\\r\\n  \\"FOOTER_BG\\": \\"#0f0f0f\\",\\r\\n  \\"NAV_BG\\": \\"#1e1e1e\\"\\r\\n}\\r\\n```\\r\\n\\r\\n## Using Theme Variables in QSS/SCSS\\r\\n\\r\\n### Basic Widget Styling\\r\\n\\r\\n```scss\\r\\nQWidget {\\r\\n    background-color: $COLOR_BACKGROUND_1;\\r\\n    color: $COLOR_TEXT_1;\\r\\n}\\r\\n\\r\\nQPushButton {\\r\\n    background-color: $COLOR_ACCENT_1;\\r\\n    color: $COLOR_TEXT_1;\\r\\n    border-radius: $SIZE_BORDER_RADIUS;\\r\\n    border: $BORDER_1;\\r\\n}\\r\\n```\\r\\n\\r\\n### Creating Gradients with RGB Components\\r\\n\\r\\nUse the RGB variables to create dynamic gradients:\\r\\n\\r\\n```scss\\r\\nQFrame#gradientFrame {\\r\\n    background: qlineargradient(\\r\\n        x1:0, y1:0, x2:1, y2:1,\\r\\n        stop:0 rgba($CB1_R, $CB1_G, $CB1_B, 255),\\r\\n        stop:1 rgba($CB3_R, $CB3_G, $CB3_B, 255)\\r\\n    );\\r\\n}\\r\\n```\\r\\n\\r\\n### Component-Specific Styling\\r\\n\\r\\n```scss\\r\\n// Cards with custom radius\\r\\nQFrame#card {\\r\\n    background-color: $COLOR_BACKGROUND_2;\\r\\n    border-radius: $CARD_RADIUS;\\r\\n    border: $BORDER_2;\\r\\n}\\r\\n\\r\\n// Navigation elements\\r\\nQWidget#navigation {\\r\\n    background-color: $NAV_BG;\\r\\n}\\r\\n\\r\\n// Footer styling\\r\\nQWidget#footer {\\r\\n    background-color: $FOOTER_BG;\\r\\n}\\r\\n```\\r\\n\\r\\n### Complex Component Styling\\r\\n\\r\\nFor more complex components, you can create custom variables:\\r\\n\\r\\n```scss\\r\\n// Define custom gradients using theme variables\\r\\n$MY_GRADIENT: qlineargradient(\\r\\n    x1:0, y1:0, x2:1, y2:0.869,\\r\\n    stop:0 $COLOR_BACKGROUND_1,\\r\\n    stop:1 $COLOR_BACKGROUND_3\\r\\n);\\r\\n\\r\\nQMainWindow#customWindow {\\r\\n    background: $MY_GRADIENT;\\r\\n    \\r\\n    QPushButton {\\r\\n        background-color: $COLOR_ACCENT_2;\\r\\n        &:hover {\\r\\n            background-color: $COLOR_ACCENT_1;\\r\\n        }\\r\\n    }\\r\\n}\\r\\n```\\r\\n\\r\\n### Form Elements with Dynamic Borders\\r\\n\\r\\n```scss\\r\\nQLineEdit, QComboBox {\\r\\n    background-color: $COLOR_BACKGROUND_2;\\r\\n    border: 2px solid $COLOR_BACKGROUND_4;\\r\\n    border-radius: 8px;\\r\\n    padding: 8px;\\r\\n    \\r\\n    &:focus {\\r\\n        border-color: $COLOR_ACCENT_1;\\r\\n    }\\r\\n}\\r\\n```\\r\\n\\r\\n### Status Indicators\\r\\n\\r\\n```scss\\r\\n// Use accent colors for status indicators\\r\\n.status-success {\\r\\n    color: $COLOR_ACCENT_1;\\r\\n    border: 1px solid $COLOR_ACCENT_1;\\r\\n}\\r\\n\\r\\n.status-warning {\\r\\n    color: $COLOR_ACCENT_2;\\r\\n    border: 1px solid $COLOR_ACCENT_2;\\r\\n}\\r\\n\\r\\n.status-error {\\r\\n    color: $COLOR_ACCENT_3;\\r\\n    border: 1px solid $COLOR_ACCENT_3;\\r\\n}\\r\\n```\\r\\n\\r\\n## Best Practices\\r\\n\\r\\n### 1. Use Semantic Variable Names\\r\\nCreate meaningful variable names for your custom styles:\\r\\n\\r\\n```scss\\r\\n$CARD_BACKGROUND: $COLOR_BACKGROUND_2;\\r\\n$HEADER_TEXT: $COLOR_TEXT_1;\\r\\n$BUTTON_PRIMARY: $COLOR_ACCENT_1;\\r\\n```\\r\\n\\r\\n### 2. Leverage the Color Hierarchy\\r\\n- Use `$COLOR_BACKGROUND_1` for main backgrounds\\r\\n- Use `$COLOR_BACKGROUND_2` for cards and panels  \\r\\n- Use `$COLOR_BACKGROUND_3` for nested elements\\r\\n- Use accent colors for interactive elements\\r\\n\\r\\n### 3. Create Reusable Mixins\\r\\nFor complex styles, create SCSS mixins:\\r\\n\\r\\n```scss\\r\\n@mixin card-style {\\r\\n    background-color: $COLOR_BACKGROUND_2;\\r\\n    border-radius: $CARD_RADIUS;\\r\\n    border: $BORDER_2;\\r\\n    padding: 16px;\\r\\n}\\r\\n\\r\\n.my-card {\\r\\n    @include card-style;\\r\\n}\\r\\n```\\r\\n\\r\\n### 4. Use RGB Components for Transparency\\r\\nCreate semi-transparent overlays using RGB variables:\\r\\n\\r\\n```scss\\r\\n.overlay {\\r\\n    background-color: rgba($CB1_R, $CB1_G, $CB1_B, 0.8);\\r\\n}\\r\\n```\\r\\n\\r\\n### 5. Theme-Aware Animations\\r\\nCreate animations that work with any theme:\\r\\n\\r\\n```scss\\r\\nQPushButton {\\r\\n    background-color: $COLOR_ACCENT_2;\\r\\n    transition: background-color 0.3s ease;\\r\\n    \\r\\n    &:hover {\\r\\n        background-color: $COLOR_ACCENT_1;\\r\\n    }\\r\\n}\\r\\n```\\r\\n\\r\\n## Dynamic Theme Switching\\r\\n\\r\\nWhen users switch themes, all variables are automatically updated, and your styles will reflect the new color scheme without any code changes.\\r\\n\\r\\n## Example: Complete Component\\r\\n\\r\\n```scss\\r\\n// Dashboard card component\\r\\n#DashboardCard {\\r\\n    background: qlineargradient(\\r\\n        x1:0, y1:0, x2:1, y2:1,\\r\\n        stop:0 $COLOR_BACKGROUND_2,\\r\\n        stop:1 $COLOR_BACKGROUND_3\\r\\n    );\\r\\n    border-radius: $CARD_RADIUS;\\r\\n    border: $BORDER_2;\\r\\n    \\r\\n    QLabel#title {\\r\\n        color: $COLOR_TEXT_1;\\r\\n        font-size: 16px;\\r\\n        font-weight: bold;\\r\\n    }\\r\\n    \\r\\n    QLabel#value {\\r\\n        color: $COLOR_ACCENT_1;\\r\\n        font-size: 24px;\\r\\n        font-weight: bold;\\r\\n    }\\r\\n    \\r\\n    QPushButton#action {\\r\\n        background-color: $COLOR_ACCENT_2;\\r\\n        color: $COLOR_TEXT_1;\\r\\n        border-radius: 6px;\\r\\n        padding: 8px 16px;\\r\\n        \\r\\n        &:hover {\\r\\n            background-color: $COLOR_ACCENT_1;\\r\\n        }\\r\\n    }\\r\\n}\\r\\n```\\r\\n\\r\\nBy using these auto-generated theme variables, you create styles that automatically adapt to any theme defined in your JSON configuration, ensuring consistency and making theme switching seamless for your users."},{"id":"v-201-released","metadata":{"permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/v-201-released","editUrl":"https://github.com/SpinnCompany/Docs-QT-PyQt-PySide-Custom-Widgets/tree/main/blog/2025-11-12-v-201-released.md","source":"@site/blog/2025-11-12-v-201-released.md","title":"V 2.0.1 Released","description":"Qt Custom Widgets v2.0.1 Released","date":"2025-11-12T00:00:00.000Z","tags":[{"inline":true,"label":"PySide6","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/py-side-6"},{"inline":true,"label":"Python","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/python"},{"inline":true,"label":"GUI","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/gui"},{"inline":true,"label":"Custom Widgets","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/custom-widgets"},{"inline":true,"label":"Tutorial","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/tutorial"},{"inline":true,"label":"version","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/version"},{"inline":true,"label":"news","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/news"}],"readingTime":2.02,"hasTruncateMarker":false,"authors":[{"name":"Khamisi Kibet","title":"Creator of Qt Custom Widgets","url":"https://github.com/khamisikibet","email":"khamisikibet@gmail.com","imageURL":"https://github.com/khamisikibet.png","key":"Khamisi Kibet","page":null}],"frontMatter":{"authors":["Khamisi Kibet"],"date":"2025-11-12","slug":"v-201-released","tags":["PySide6","Python","GUI","Custom Widgets","Tutorial","version","news"],"title":"V 2.0.1 Released"},"unlisted":false,"prevItem":{"title":"Qt Theme Styling Guide: Qss/Css Stylesheet","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/qt-theme-styling-guide-qsscss-stylesheet"},"nextItem":{"title":"Introducing the New Dashboard UI","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/introducing-the-new-dashboard-ui"}},"content":"## Qt Custom Widgets v2.0.1 Released\\r\\n\\r\\nWe\u2019re excited to announce the release of **Qt Custom Widgets 2.0.1** \u2014 a refined update that brings even more power and flexibility to your PyQt and PySide GUI development.\\r\\n\\r\\nThis release focuses on **performance improvements**, **new custom widgets**, and a **streamlined command-line interface (CLI)** that now lets you launch Qt Designer with all custom widgets preloaded.\\r\\n\\r\\n---\\r\\n\\r\\n### What\u2019s New in 2.0.1\\r\\n\\r\\n#### More Custom Widgets\\r\\n\\r\\nThis version introduces several new widgets designed to enhance both functionality and design flexibility. Each widget can be used directly in Qt Designer or instantiated in Python code, fully integrated with your preferred Qt library (PySide6, PySide2, PyQt6, or PyQt5).\\r\\n\\r\\n#### Launch Qt Designer with Plugins\\r\\n\\r\\nThe new CLI now supports launching **Qt Designer** directly from your environment, with optional loading of all **Custom Widgets** plugins.\\r\\n\\r\\nTo open Designer with your custom widgets automatically loaded, simply run:\\r\\n\\r\\n```bash\\r\\nCustom_Widgets --start-designer --plugins\\r\\n```\\r\\n\\r\\nIf you prefer to launch Designer without plugins, just run:\\r\\n\\r\\n```bash\\r\\nCustom_Widgets --start-designer\\r\\n```\\r\\n\\r\\nThis feature ensures a seamless integration between your environment and Designer, making your workflow faster and more reliable.\\r\\n\\r\\n#### Improved JSON Stylesheet\\r\\n\\r\\nThe JSON-based stylesheet system has been updated for better theme management. You can now apply light, dark, or custom themes more efficiently with improved property mapping and rendering accuracy.\\r\\n\\r\\n#### Minor Fixes and Performance Improvements\\r\\n\\r\\nThis update includes improved logging, faster UI monitoring, and stability enhancements across all supported platforms.\\r\\n\\r\\n---\\r\\n\\r\\n### Updated Command-Line Interface (CLI)\\r\\n\\r\\nThe **Custom Widgets CLI** is designed to automate repetitive tasks in Qt development. It now supports file monitoring, UI conversion, Designer launching, and project setup \u2014 all in one tool.\\r\\n\\r\\n#### Monitor UI Files for Changes\\r\\n\\r\\n```bash\\r\\nCustom_Widgets --monitor-ui path/to/file.ui --qt-library PySide6\\r\\n```\\r\\n\\r\\nAutomatically converts `.ui` files to Python when changes are detected.\\r\\n\\r\\n#### Convert UI Files to Python\\r\\n\\r\\n```bash\\r\\nCustom_Widgets --convert-ui path/to/file.ui --qt-library PySide6\\r\\n```\\r\\n\\r\\nInstantly converts `.ui` files to `.py` while preserving all custom widget imports.\\r\\n\\r\\n#### Launch Designer\\r\\n\\r\\n```bash\\r\\nCustom_Widgets --start-designer --plugins\\r\\n```\\r\\n\\r\\nOpens Qt Designer with **Custom Widgets** automatically loaded.\\r\\n\\r\\n#### Create a New Project\\r\\n\\r\\n```bash\\r\\nCustom_Widgets --create-project\\r\\n```\\r\\n\\r\\nSets up a ready-to-use project structure for developing with **Qt Custom Widgets**.\\r\\n\\r\\nFor detailed command usage:\\r\\n\\r\\n```bash\\r\\nCustom_Widgets --help\\r\\n```\\r\\n\\r\\n---\\r\\n\\r\\n### Upgrade Now\\r\\n\\r\\nTo upgrade to version 2.0.1, run:\\r\\n\\r\\n```bash\\r\\npip install --upgrade QT-PyQt-PySide-Custom-Widgets\\r\\n```\\r\\n\\r\\nOr visit the official PyPI page:\\r\\n[https://pypi.org/project/QT-PyQt-PySide-Custom-Widgets/](https://pypi.org/project/QT-PyQt-PySide-Custom-Widgets/)"},{"id":"introducing-the-new-dashboard-ui","metadata":{"permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/introducing-the-new-dashboard-ui","editUrl":"https://github.com/SpinnCompany/Docs-QT-PyQt-PySide-Custom-Widgets/tree/main/blog/2025-11-07-introducing-the-new-dashboard-ui.md","source":"@site/blog/2025-11-07-introducing-the-new-dashboard-ui.md","title":"Introducing the New Dashboard UI","description":"We\u2019re excited to introduce the new modern Dashboard UI for the Docs-QT-PyQt-PySide-Custom-Widgets project! \ud83c\udfa8","date":"2025-11-07T00:00:00.000Z","tags":[{"inline":true,"label":"Dashboard","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/dashboard"},{"inline":true,"label":"PySide6","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/py-side-6"},{"inline":true,"label":"Custom Widgets","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/custom-widgets"},{"inline":true,"label":"Design","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/design"}],"readingTime":0.9,"hasTruncateMarker":true,"authors":[{"name":"Khamisi Kibet","title":"Creator of Qt Custom Widgets","url":"https://github.com/khamisikibet","email":"khamisikibet@gmail.com","imageURL":"https://github.com/khamisikibet.png","key":"Khamisi Kibet","page":null}],"frontMatter":{"authors":["Khamisi Kibet"],"date":"2025-11-07","slug":"introducing-the-new-dashboard-ui","tags":["Dashboard","PySide6","Custom Widgets","Design"],"title":"Introducing the New Dashboard UI"},"unlisted":false,"prevItem":{"title":"V 2.0.1 Released","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/v-201-released"},"nextItem":{"title":"Welcome to the Qt Custom Widgets Blog","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/welcome-to-the-qt-custom-widgets-blog"}},"content":"We\u2019re excited to introduce the **new modern Dashboard UI** for the *Docs-QT-PyQt-PySide-Custom-Widgets* project! \ud83c\udfa8  \\r\\nIt\u2019s built with **PySide6**, styled for dark mode, and designed to provide a seamless development experience.\\r\\n\\r\\n\x3c!-- truncate --\x3e\\r\\n\\r\\n## \ud83d\ude80 Highlights\\r\\n\\r\\nHere\u2019s what\u2019s new in the Dashboard:\\r\\n\\r\\n- **Responsive layout** with sidebar, header, and content sections.  \\r\\n- **Dark mode** optimized interface.  \\r\\n- **Quick actions** to create and manage blog posts easily.  \\r\\n- **Tailwind-inspired design** for better visual consistency.  \\r\\n- **Modular includes** for sidebar, header, and footer \u2014 making it easy to reuse across pages.\\r\\n\\r\\n## \ud83e\udde9 Technologies\\r\\n\\r\\nThe dashboard is powered by:\\r\\n- **PySide6** for UI logic  \\r\\n- **Tailwind CSS** for layout styling  \\r\\n- **Jinja templates** for component structure  \\r\\n- **Docusaurus** for the documentation and blog system\\r\\n\\r\\n## \ud83d\udee0\ufe0f Upcoming Features\\r\\n\\r\\nNext, we\u2019re adding:\\r\\n- Markdown live preview for blog creation.  \\r\\n- Automatic `.md` generation from the dashboard form.  \\r\\n- Post synchronization with your hosted docs site at  \\r\\n  \ud83d\udc49 [qtcustomwidgets.spinncode.com/blog](https://qtcustomwidgets.spinncode.com/blog)\\r\\n\\r\\n## \ud83d\udcac Final Thoughts\\r\\n\\r\\nThis marks the beginning of a unified workflow \u2014 write, preview, and publish your documentation or blogs directly from the **Dashboard UI**.\\r\\n\\r\\nStay tuned for the next update:  \\r\\n> \ud83e\udde0 \u201cHow We Integrated Docusaurus Build Automation with PySide6 Backend\u201d"},{"id":"welcome-to-the-qt-custom-widgets-blog","metadata":{"permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/welcome-to-the-qt-custom-widgets-blog","editUrl":"https://github.com/SpinnCompany/Docs-QT-PyQt-PySide-Custom-Widgets/tree/main/blog/2025-11-07-welcome-to-the-qt-custom-widgets-blog.md","source":"@site/blog/2025-11-07-welcome-to-the-qt-custom-widgets-blog.md","title":"Welcome to the Qt Custom Widgets Blog","description":"Welcome to the official Qt Custom Widgets Blog, hosted on Spinncode! \ud83c\udf89","date":"2025-11-07T00:00:00.000Z","tags":[{"inline":true,"label":"Qt","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/qt"},{"inline":true,"label":"PySide6","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/py-side-6"},{"inline":true,"label":"PyQt","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/py-qt"},{"inline":true,"label":"Custom Widgets","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/custom-widgets"},{"inline":true,"label":"Docusaurus","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/docusaurus"}],"readingTime":1.39,"hasTruncateMarker":true,"authors":[{"name":"Khamisi Kibet","title":"Creator of Qt Custom Widgets","url":"https://github.com/khamisikibet","email":"khamisikibet@gmail.com","imageURL":"https://github.com/khamisikibet.png","key":"Khamisi Kibet","page":null}],"frontMatter":{"authors":["Khamisi Kibet"],"date":"2025-11-07","slug":"welcome-to-the-qt-custom-widgets-blog","tags":["Qt","PySide6","PyQt","Custom Widgets","Docusaurus"],"title":"Welcome to the Qt Custom Widgets Blog"},"unlisted":false,"prevItem":{"title":"Introducing the New Dashboard UI","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/introducing-the-new-dashboard-ui"}},"content":"Welcome to the official **Qt Custom Widgets Blog**, hosted on [Spinncode](https://spinncode.com)! \ud83c\udf89  \\r\\n\\r\\nThis space is dedicated to sharing tutorials, behind-the-scenes updates, and deep dives into **modern PySide6 and PyQt widget design**.\\r\\n\\r\\n\x3c!-- truncate --\x3e\\r\\n\\r\\n## \ud83d\udca1 Why This Blog Exists\\r\\n\\r\\nWhen building modern desktop apps with Qt for Python, you quickly realize that many of the best UI ideas need custom widgets \u2014 not just the defaults.  \\r\\nThis blog will help you:\\r\\n- Learn how to design and implement reusable custom widgets.\\r\\n- Explore advanced PySide6 and PyQt UI techniques.\\r\\n- Follow development updates for the **Docs-QT-PyQt-PySide-Custom-Widgets** module.\\r\\n\\r\\nWhether you\u2019re creating dashboards, admin panels, or interactive desktop tools \u2014 you\u2019ll find practical examples here.\\r\\n\\r\\n## \ud83d\ude80 What You Can Expect\\r\\n- \ud83e\udde9 Step-by-step widget tutorials  \\r\\n- \ud83c\udfa8 Modern UI design ideas  \\r\\n- \u2699\ufe0f Integration tips for Docusaurus documentation  \\r\\n- \ud83d\udcac Community discussions & new releases  \\r\\n\\r\\nOur upcoming posts will include topics like:\\r\\n- Building **Dynamic Progress Bars** with QProperty animations.\\r\\n- Creating **Designer-friendly Widgets** with custom properties.\\r\\n- Structuring PySide6 projects for maintainability and scalability.\\r\\n\\r\\n## \ud83e\uddf1 About the Project\\r\\n\\r\\nThe **Docs-QT-PyQt-PySide-Custom-Widgets** project is a growing toolkit of pre-built, stylized Qt widgets that you can use in your apps or preview in Qt Designer.  \\r\\nIt includes:\\r\\n- Ready-made reusable widgets\\r\\n- Integrated resource management\\r\\n- A project generator (\u201cProject Maker\u201d) for faster setup\\r\\n\\r\\nYou can explore the docs at  \\r\\n\ud83d\udc49 [https://qtcustomwidgets.spinncode.com](https://qtcustomwidgets.spinncode.com)\\r\\n\\r\\n## \ud83d\udc68\u200d\ud83d\udcbb About the Author\\r\\n\\r\\nI\u2019m **Khamisi Kibet**, a Python developer from Kenya \ud83c\uddf0\ud83c\uddea passionate about creating **modern, lightweight desktop UIs**.  \\r\\nI believe in building one line of code at a time \u2014 clean, efficient, and scalable.\\r\\n\\r\\nFollow updates here or on [Spinncode.com](https://spinncode.com).\\r\\n\\r\\n---\\r\\n\\r\\n> \ud83d\udcac *\u201cDesign it once, use it everywhere \u2014 from Designer to production.\u201d*  \\r\\n> \u2014 *Qt Custom Widgets Team*"}]}}')}}]);